<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;

/**
 * Serves the full SmartPRS prototype engine (113 screens, SCREENS config + SEED
 * + renderers) behind Laravel auth. Injects the logged-in user's role so the
 * prototype's role-based navigation matches, skips the prototype's mock login,
 * and wires a real Laravel logout. Live DB data is layered in progressively.
 */
class AppController extends Controller
{
    private const ROLE_MAP = [
        'super_admin' => 'Super Admin',
        'admin' => 'Admin',
        'hr_manager' => 'HR Manager',
        'field_agent' => 'Field Agent',
        'employee' => 'Employee',
    ];

    /**
     * The module groups the current user's tenant plan includes.
     * Returns null (= UNRESTRICTED) for: the platform super admin; a tenant with
     * no plan; a plan with no features; OR a legacy/free-text plan whose feature
     * keys are not the recognised module-group keys (e.g. the seeded Growth plan
     * stored ['payroll','attendance','compliance']). Enforcement only kicks in
     * when the plan was configured with the new module-group system — otherwise
     * we never gate, so a tenant is never accidentally stripped of most modules.
     * The recognised group keys must match SaasController::MODULE_GROUPS and the
     * front-end PLAN_GROUP_NAV.
     */
    private const PLAN_GROUP_KEYS = [
        'employees', 'attendance', 'leave', 'payroll', 'statutory',
        'requests', 'field', 'performance', 'kb', 'reports',
    ];

    private static function resolvePlanModules($user): ?array
    {
        try {
            $tid = $user->tenant_id ?? null;
            if (! $tid) {
                return null;   // platform super admin — full access
            }
            if (! \Illuminate\Support\Facades\Schema::hasTable('tenants') || ! \Illuminate\Support\Facades\Schema::hasTable('plans')) {
                return null;
            }
            $planId = \Illuminate\Support\Facades\DB::table('tenants')->where('id', $tid)->value('plan_id');
            if (! $planId) {
                return null;   // tenant has no plan assigned → don't gate
            }
            $features = \Illuminate\Support\Facades\DB::table('plans')->where('id', $planId)->value('features');
            $groups = $features ? (json_decode($features, true) ?: []) : [];
            $groups = array_values(array_filter(array_map('strval', is_array($groups) ? $groups : [])));
            if (! count($groups)) {
                return null;   // empty list → unrestricted (safe)
            }
            // Only gate when EVERY key is a recognised module-group key — that is
            // only ever produced by the new Plans UI (checkboxes). If ANY key is
            // unknown (e.g. the seeded Growth plan's free-text 'compliance'), the
            // plan predates the module-group system → do NOT gate (unrestricted),
            // so legacy/seeded plans never hide most of the app.
            $unknown = array_diff($groups, self::PLAN_GROUP_KEYS);
            if (count($unknown)) {
                return null;   // legacy/free-text plan → unrestricted
            }

            return $groups;   // all keys recognised → enforce exactly these
        } catch (\Throwable $e) {
            return null;   // never block the app on a plan-resolution error
        }
    }

    public function show(Request $request, ?string $screen = null)
    {
        // rev185: a passkey-gated demo session whose window ended (or was revoked)
        // is logged out here and sent back to its entry page for a fresh request.
        if ($demoBack = DemoAccessController::expiredRedirect($request)) {
            return redirect($demoBack);
        }
        // rev 170: a freshly provisioned admin must CREATE their password before
        // the app opens (fixes the silent-email lock-out after paid signup).
        if (AuthController::mustSetPassword($request->user())) {
            return redirect('/app/first-password');
        }

        $path = resource_path('prototype/app.html');
        abort_unless(is_file($path), 404, 'Prototype not found.');

        $html = file_get_contents($path);
        $user = $request->user();
        $role = self::ROLE_MAP[$user->getRoleNames()->first() ?? 'admin'] ?? 'Admin';

        // Subscription lifecycle (rev 75) — banner + lock-out state for this login.
        // rev 103: on-prem editions are perpetual — no renew banners, ever.
        $subInfo = \App\Services\Edition::isOnPrem()
            ? ['state' => 'active', 'end' => null, 'daysLeft' => 9999]
            : \App\Services\SubscriptionService::state($user->tenant_id ? (int) $user->tenant_id : null);

        $cfg = json_encode([
            'role' => $role,
            'planModules' => self::resolvePlanModules($user),   // null = unrestricted; else allowed module-group keys
            'csrf' => csrf_token(),
            'logoutUrl' => route('logout'),
            'dataUrl' => route('app.data'),
            'kbUrl' => route('app.kb'),
            'attReportUrl' => route('app.attreport'),
            'attLogsUrl' => url('/app/attendance-report/logs'),
            'attRatingUrl' => route('app.attreport.rating'),
            'attPdfUrl' => route('app.attreport.pdf'),
            'settingsUrl' => route('app.settings'),
            'settingsSaveUrl' => route('app.settings.save'),
            'kbReorderUrl' => url('/app/kb/reorder'),
            'punchUrl' => route('app.punch'),
            'punchStatusUrl' => route('app.punch.status'),
            'mailUrl' => route('app.mail'),
            'mailSaveUrl' => route('app.mail.save'),
            'mailTestUrl' => route('app.mail.test'),
            'brandingUrl' => route('app.branding'),
            'brandingSaveUrl' => route('app.branding.save'),
            'brandingLogoUrl' => route('app.branding.logo.upload'),
            'appLogoUrl' => route('app.branding.applogo'),
            'appLogo' => \App\Http\Controllers\ConfigController::appLogoUrlFor($user->tenant_id ?? null),   // rev184 — per-client sidebar logo (fallback: default product logo)
            'empImportUrl' => route('app.employees.import'),
            'empTemplateUrl' => route('app.employees.template'),
            'empExportUrl' => route('app.employees.export'),   // F6 — full employee export (CSV + XLSX)
            'stateUrl' => route('app.state'),
            'stateSaveUrl' => route('app.state.save'),
            'empStoreUrl' => route('app.employees.store'),
            'leavesUrl' => route('app.leaves'),
            'leaveApplyUrl' => route('app.leaves.apply'),
            'leaveBalancesBase' => url('/app/leaves/balances'),   // + /{employee}
            'leaveDecideUrl' => url('/app/leaves'),   // + /{id}/decide
            'approvalsUrl' => route('app.approvals'),
            'requestsBase' => url('/app/requests'),   // + /{module}  and  /{module}/{id}/decide
            'schemesBase' => url('/app/schemes'),     // rev 115: + /for-me, /{id}/withdraw
            'mobileDevBase' => url('/app/mobile-devices'),  // rev 119: + /list, /{id}/approve|reject|revoke
            'masterBase' => url('/app/master'),       // + /{type}, /{type}/{id}/delete
            'cocUrl' => url('/app/code-of-conduct'),   // Code of Conduct read + acknowledge (+ /ack)
            'bioUrl' => url('/app/biometric-config'),   // rev157: Biometric Device Setup screen (test + sync)
            'docBase' => url('/app/documents-mgr'),   // rev161: Documents — list (+?q=), /upload, /{id}/download, /{id}/delete
            'incentiveBase' => url('/app/incentive'),   // commission/incentive calc: /template /calculate /commit
            'finYearBase' => url('/app/fin-year'),       // financial year: GET + /set
            'mySubBase' => url('/app/my-subscription'),   // tenant self-serve billing: GET + /quote /renew/order /renew/complete
            'transfersBase' => url('/app/transfers'),     // + /{id}/letter (Transfer Order PDF)
            'incrementsBase' => url('/app/increments'),   // + /{id}/letter (PDF) + /{id}/apply (rev 83b)
            'liveSalaryUrl' => url('/app/live-salary/data'),   // running-month earned-till-today panel
            'attBulkBase' => url('/app/attendance-bulk'),      // bulk punches: /template /upload /{batch}/decide /row/{id}/delete
            'empBulkDeleteUrl' => url('/app/employees/bulk-delete'),   // soft-delete selected employees (admin)
            'salaryRunsUrl' => route('app.salaryruns'),
            'salaryRunsBase' => url('/app/salary-runs'),   // + /{id}/decide  and  /bulk  and  /{id}/sheet
            'payslipBase' => url('/app/payslip'),           // + /{code}/pdf?month=
            'salaryLinesBase' => url('/app/salary-lines'),  // + /{id}/decide, /bulk, /{id}/acknowledge
            'complianceUrl' => url('/app/compliance-alerts'),       // DRA/PCC expiry alerts
            'complianceRunUrl' => url('/app/compliance-alerts/run'),
            'payrollPreviewUrl' => url('/app/payroll/preview'),     // Generate Payroll: preview a run
            'salarySimUrl' => url('/app/salary-simulate'),          // rev178 — what-if Salary Simulator (all roles)
            'bankPackBase' => url('/app/bank-pack'),                // rev181 — bank/NBFC payout & billing pack
            'calcGuideUrl' => url('/app/calc-guide'),               // rev181b — in-app Salary Calculation Guide + demo FAQs
            'payrollGenUrl' => url('/app/payroll/generate'),        // Generate Payroll: create draft run
            'reportsPreviewUrl' => url('/app/reports/preview'),     // Reports: preview a dataset
            'reportsExportUrl' => url('/app/reports/export'),       // Reports: CSV download
            'statutoryReportBase' => url('/app/statutory-report'),  // + /{type} (gratuity|pt)
            'lettersBase' => url('/app/letters'),                   // + /{id}/pdf (merged letter)
            'computedBase' => url('/app/computed'),                 // + /{type} computed read views
            'idcardBase' => url('/app/idcard'),                     // + /{code}/pdf
            'sendMessageUrl' => url('/app/send-message'),           // broadcast email
            'pointsAutoApplyUrl' => url('/app/points/auto-apply'),  // auto-award attendance points
            'testsBase' => url('/app/tests'),                       // tests engine (questions + take)
            'onboardingBase' => url('/app/onboarding'),             // onboarding checklist workflow
            'performanceBase' => url('/app/performance'),           // performance review workflow
            'myPhotoUrl' => url('/app/my-photo'),                   // self-service employee photo
            'essMeUrl' => url('/app/ess/me'),                       // employee self-service snapshot
            'essUpdateUrl' => url('/app/ess/update'),               // rev162: employee self-edit personal details
            'deviceBase' => url('/app/device'),                     // biometric device in-app sync
            'recruitmentBase' => url('/app/recruitment'),          // ATS pipeline
            'offrollAgentBase' => url('/app/offroll-agent'),        // off-roll agent KYC
            'waTplBase' => url('/app/wa-templates'),                // rev 92: WhatsApp template registry
            'helpBase' => url('/app/help'),                         // rev 100: per-screen ⓘ guide
            'billingBase' => url('/app/billing'),                   // SaaS billing (super admin)
            'dashboardStatsUrl' => url('/app/dashboard/stats'),     // live dashboard widgets
            'searchUrl' => url('/app/search'),                      // global top-bar search
            'usersUrl' => url('/app/users'),                        // company user logins
            'usersBase' => url('/app/users'),                       // + /{id}/invite, /{id}/status
            'changePasswordUrl' => url('/app/change-password'),
            'saasTenantsUrl' => url('/app/saas/tenants'),    // SaaS platform: tenant provisioning
            'demoReqUrl' => url('/app/saas/demo-requests'),  // rev185: passkey-gated demo register (Super Admin)
            'demoExp' => (int) (($request->session()->get('demo_pass') ?: [])['exp'] ?? 0),   // rev185: passkey expiry (epoch s; 0 = not a passkey demo)
            'demoBack' => (string) (($request->session()->get('demo_pass') ?: [])['back'] ?? ''),
            'saasPlansUrl' => url('/app/saas/plans'),
            'saasPlanDeleteUrl' => url('/app/saas/plans/delete'),
            'screen' => $screen,
            // rev 97: public live demo — start the guided tour (?tour=1) and
            // mark demo-workspace sessions (floating tour button + safety).
            'tour' => request()->boolean('tour') ? 1 : 0,
            'isDemo' => \App\Http\Controllers\DemoAccessController::isDemoTenant($user->tenant_id) ? 1 : 0,
            // rev 105: team-driven personal demo (PIN-entered) — unrestricted.
            'demoTeam' => session('demo_team') ? 1 : 0,
            // rev 103: on-premise editions (SmartPRS-L1/L2/L3). saas = full.
            'edition' => \App\Services\Edition::current(),
            'editionLevel' => \App\Services\Edition::level(),
            'editionHide' => \App\Services\Edition::hiddenNavIds(),
            // rev 107: update & licensing (on-prem Updates screen + version).
            'updatesBase' => url('/app/updates'),
            'appVersion' => config('smartprs.version'),
            'user' => $user->name,
            'userEmail' => $user->email,
            'company' => optional($user->company)->name,
            'portalCompany' => session('portal_company_id'),   // from /c/{slug} branded login
            // Subscription lifecycle (rev 75): drives the renew banner + lock-out UI.
            'subState' => $subInfo['state'],                 // active|grace|locked|none
            'subEnd' => $subInfo['end'] ? $subInfo['end']->format('d M Y') : '',
            'subDays' => $subInfo['daysLeft'],
        ], JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_HEX_AMP);

        // Hide the prototype's mock login to avoid a flash before auto-enter.
        // NOTE: the prototype's JS builds HTML strings containing literal
        // </head> and </body>, so we must inject ONLY at the real document tags
        // (first </head>, last </body>) — never a blind replace-all.
        $style = <<<CSS
<style>
/* rev 120: kill horizontal page scroll on phones — nothing should be wider than
   the viewport. The min-width:0 lets flex children actually shrink (the classic
   cause of a row that refuses to fit). */
html,body{max-width:100%;overflow-x:hidden;}
.main-wrap,.content,.topbar{min-width:0;max-width:100%;}
.content{overflow-x:hidden;}
#login-page{display:none!important}
#smartprs-burger{display:inline-flex}
#smartprs-mlogo{display:none}
#smartprs-ov{display:none}
/* rev 88: the burger now ALSO works on desktop — it hides/expands the whole
   sidebar (body.nav-hidden) so tables get the full screen width. Remembered
   per browser (localStorage sp_navhide). Mobile keeps the slide-in drawer. */
@media (min-width: 901px){
  body.nav-hidden .sidebar{display:none}
  body.nav-hidden .main-wrap{margin-left:0 !important}
}
/* Topbar layout: keep the page title on one line (it renders at 24px and was
   wrapping into the Punch button), and give the title block room while the
   action icons keep their own space on the right. */
.topbar > div:first-child{flex:0 1 auto;min-width:0;margin-right:8px}
.topbar .page-title{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:1.2}
.topbar .breadcrumb{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* rev 88 (Ejaz live check): on smaller desktop widths / 125% Windows scaling the
   avatar + logout were pushed OFF-SCREEN. The wide topbar members (company
   switcher + both searches) must SHRINK instead — icons keep their size and the
   right edge always stays visible. */
.topbar-actions{flex:1 1 auto;flex-wrap:nowrap;min-width:0;justify-content:flex-end}
.topbar-actions .company{min-width:120px;flex:0 1 220px}
.topbar-actions .company .cname{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.topbar-actions .topbar-search{min-width:90px;flex:0 1 220px}
.topbar-actions .topbar-btn,.topbar-actions .topbar-avatar{flex:0 0 auto}
#sp-search{min-width:80px}
@media (max-width: 1350px) and (min-width: 901px){
  .topbar{padding:0 14px;gap:10px}
  .topbar-actions{gap:8px;min-width:0}
  #sp-search{width:130px !important}
  .topbar-actions .csub{display:none}
  /* rev 120: in this narrow-desktop band (e.g. a ~990px window) the company
     switcher + avatar + logout were colliding and clipping. Let the company name
     shrink to an ellipsis so the action buttons always stay fully on screen. */
  .topbar-actions .company{min-width:0 !important;flex:0 1 180px !important;max-width:180px}
}
@media (max-width: 1120px) and (min-width: 901px){
  /* no room for the search box here — drop it so nothing clips off the right */
  #sp-search-wrap,.topbar-search,#sp-search{display:none !important}
  .topbar-actions .company{flex:0 1 150px !important;max-width:150px}
}
@media (max-width: 900px){
  .sidebar{transform:translateX(-100%);transition:transform .25s ease;z-index:120}
  body.nav-open .sidebar{transform:translateX(0)}
  .main-wrap{margin-left:0 !important}
  #smartprs-burger{display:inline-flex !important}
  body.nav-open #smartprs-ov{display:block;position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:110}
  .feat-grid,.dash-grid,.dash-grid2,.price-grid,.fgrid,.form-grid,.form-grid.col2,.form-grid.col4{grid-template-columns:1fr !important}
  .stats-grid,.kpi-strip{grid-template-columns:1fr 1fr !important;gap:12px !important}
  .stat-card{padding:14px !important}
  .stat-card .icon{width:34px;height:34px;font-size:14px;margin-bottom:10px}
  .stat-card h3{font-size:20px}
  .stat-card p{font-size:11px}
  .kpi{padding:14px}
  .kpi h3{font-size:19px}
  .content{padding:14px !important}
  /* rev 120: TOPBAR must never overflow on a phone. Keep only the essentials
     (burger, mobile logo, Punch In, company icon, profile, logout); hide search,
     breadcrumb, title, bell, import/export. Reduce padding + shrink-to-fit. */
  .topbar{height:auto !important;min-height:54px;padding:8px 10px !important;gap:8px !important;overflow:hidden;flex-wrap:nowrap;}
  .topbar > div:first-child{min-width:0;flex:0 1 auto;overflow:hidden;}
  .breadcrumb,.page-title{display:none !important;}
  #smartprs-mlogo{display:inline-flex !important;align-items:center;gap:6px;flex:0 0 auto;}
  #smartprs-mlogo b{display:none !important;}   /* rev 121: the "SmartPRS" wordmark was clipping to "S" — keep just the icon on phones */
  .topbar-actions{gap:8px !important;min-width:0;flex:1 1 auto;justify-content:flex-end;}
  #sp-search-wrap,.topbar-search{display:none !important;}
  .topbar-actions .topbar-btn:not(.sp-keep){display:none !important;}
  .topbar-actions .csub{display:none !important;}
  .topbar-actions .company{max-width:34vw;padding:6px 9px;flex:0 1 auto;min-width:0;}
  /* rev 121: the company chip must NOT collapse — when it shrank to ~18px the GRP
     icon spilled out and the avatar overlapped it. Lock the icon to its size. */
  .topbar-actions .company .cico{flex:0 0 auto !important;}
  .topbar-actions .company .cname{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:13px;}
  .cdrop{max-width:84vw;}
  .pg-head,.page-header{flex-direction:column;align-items:flex-start;gap:10px;}
  .pg-actions{margin-left:0 !important;width:100%;}
}
@media (max-width: 900px){
  /* rev 122: Geo-Fence map. Leaflet gives its panes/controls z-index up to ~1000;
     because the map element isn't its own stacking context those leaked ABOVE the
     mobile nav drawer (z-index 120) — the map painted over the open menu. isolate it
     so all its internal z-indexes are contained below the drawer. Also stack the
     rule list above a full-width map (no min-width overflow) on phones. Desktop is
     untouched (this whole block only applies <=900px, where the drawer exists). */
  .geo-split{flex-direction:column !important;}
  .geo-list{width:100% !important;min-width:0 !important;max-height:240px !important;border-right:none !important;border-bottom:1px solid var(--border) !important;}
  #geo-map{min-width:0 !important;width:100% !important;height:380px !important;isolation:isolate;position:relative;z-index:0;}
}
@media (max-width: 430px){
  /* very narrow: company switcher shows only its icon, Punch In text trims */
  .topbar-actions .company .cname,.topbar-actions .company i.fa-chevron-down{display:none !important;}
  /* rev 121: icon-only, but DON'T let it shrink (that caused the GRP/avatar overlap) */
  .topbar-actions .company{max-width:none;padding:6px 8px;flex:0 0 auto !important;overflow:hidden;}
}
@media (max-width: 600px){
  th,td{padding:9px 10px !important}
  /* rev 120 (mobile/app): entry & detail MODALS use fixed 2/3-col field grids set
     inline; on a phone they cram. Force every grid inside any *-modal (req-modal,
     comm-modal, ms-modal, etc.) to a single column so fields stack and stay tappable.
     rev 121: overriding grid-template-columns:1fr did NOT collapse these inline grids
     (verified live in-browser — the inline 2-col value stuck). Switching the display
     to a flex column reliably stacks the children full-width on every modal. */
  div[id$="-modal"] [style*="grid-template-columns"]{display:flex !important;flex-direction:column !important;align-items:stretch !important;}
  div[id$="-modal"] [style*="grid-template-columns"] > *{width:100% !important;min-width:0 !important;}
  div[id$="-modal"] .card{max-width:100% !important;padding:18px 16px !important;}
  /* register/action cells wrap their buttons instead of forcing a wide row */
  td [class*="btn"]{margin-bottom:4px;}
  /* rev 122: master tables (Training Programs, FAQs, Escalations, …) are 6-8 cols
     wide and scrolled sideways on phones, cramming long text (Description/Answer)
     into a tiny column. On phones ONLY, stack each record into a card: hide the
     header row and lay each cell out as "LABEL : value". Long cells go full-width
     and justified so the text reads edge-to-edge. Tablet/desktop keep the table. */
  table.mc-table, table.mc-table tbody, table.mc-table tr, table.mc-table td{display:block;width:auto;}
  table.mc-table thead{display:none;}
  table.mc-table tr{padding:6px 2px;border-top:1px solid var(--border);}
  table.mc-table tr:first-child{border-top:none;}
  table.mc-table td{border:none !important;padding:6px 14px !important;display:flex;gap:14px;align-items:baseline;min-width:0 !important;font-size:13px;}
  table.mc-table td::before{content:attr(data-label);flex:0 0 38%;font-weight:600;font-size:11px;text-transform:uppercase;letter-spacing:.3px;color:var(--text3);}
  table.mc-table td.mc-longtext{display:block;}
  table.mc-table td.mc-longtext::before{display:block;margin-bottom:5px;flex:none;}
  table.mc-table td.mc-longtext{text-align:justify;-webkit-hyphens:auto;hyphens:auto;line-height:1.55;}
  table.mc-table td.mc-actions{justify-content:flex-end;gap:18px;padding-top:10px !important;}
  table.mc-table td.mc-actions::before{display:none;}
  table.mc-table td.mc-actions:empty{display:none;}
  /* rev 122: "How SmartPRS Works" — its cards sit in an inline 2-col grid that
     crammed the text into a ~12-char column on phones. On mobile ONLY, stack to a
     single card per row with clear spacing (flex column reliably overrides the
     inline display:grid). Tablet/desktop keep the original 2-up grid untouched. */
  .hiw-grid{display:flex !important;flex-direction:column !important;gap:16px !important;}
  .hiw-grid .hiw-card{margin-bottom:0 !important;}
  /* full-width column now reads well; justify the body with hyphenation so the
     right edge is tidy without the ragged gaps justify usually causes */
  .hiw-body{text-align:justify;-webkit-hyphens:auto;hyphens:auto;}
}
/* rev 120: any data table sitting directly in a .card scrolls sideways on small
   screens rather than blowing out the page width (most are already wrapped; this
   is the safety net for any that aren't). */
@media (max-width: 900px){
  .card > table, .card > .tbl{display:block;max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch;}
}
/* --- rev 66 UX polish: motion & interaction ONLY (palette, layout, fonts, icons unchanged) --- */
input:focus,select:focus,textarea:focus{border-color:var(--accent);outline:none}
tbody tr:hover{background:rgba(15,23,42,.025)}
html{scroll-behavior:smooth}
@media (prefers-reduced-motion: no-preference){
  .btn,button{transition:background-color .15s ease,border-color .15s ease,box-shadow .15s ease,transform .08s ease}
  .btn:active,button:active{transform:translateY(1px)}
  input,select,textarea{transition:border-color .15s ease,box-shadow .15s ease,background-color .15s ease}
  .card{transition:box-shadow .2s ease,transform .2s ease}
  a{transition:color .12s ease,opacity .12s ease}
  .nav-item{transition:background-color .15s ease,color .15s ease}
  i[onclick]{transition:transform .12s ease,opacity .12s ease;display:inline-block}
  i[onclick]:hover{transform:scale(1.15)}
  tbody tr{transition:background-color .12s ease}
  @keyframes sp-fade{from{opacity:0}to{opacity:1}}
  @keyframes sp-pop{from{opacity:0;transform:translateY(10px) scale(.99)}to{opacity:1;transform:none}}
  div[id$="-modal"],div[id$="-ov"],.modal-ov{animation:sp-fade .16s ease}
  div[id$="-modal"]>.card,div[id$="-ov"]>.card,div[id$="-ov"]>div,.modal-ov>.card,.modal-ov>div{animation:sp-pop .2s cubic-bezier(.16,.84,.44,1)}
}
/* --- rev 73: default inner padding for ALL cards (content was touching the card
   border on several screens). The base .card class ships with NO padding, so any
   screen that sets its own inline padding — including the padding:0 full-bleed
   table cards — automatically overrides this (inline styles win). --- */
.card{padding:18px 22px}
/* rev 122: themed in-app prompt (replaces the native browser prompt() that showed
   the ugly "the page at smartprs.com says" box). High z-index so it sits above the
   drawer, modals and the map. */
.sp-prompt-ov{position:fixed;inset:0;background:rgba(15,23,42,.5);z-index:100000;display:flex;align-items:center;justify-content:center;padding:18px;animation:sp-fade .15s ease}
.sp-prompt-card{background:#fff;border-radius:16px;width:100%;max-width:420px;padding:22px;box-shadow:0 20px 60px rgba(0,0,0,.32);animation:sp-pop .2s cubic-bezier(.16,.84,.44,1)}
.sp-prompt-title{font-weight:700;font-size:17px;color:var(--text);margin-bottom:6px}
.sp-prompt-msg{font-size:13px;color:var(--text2);margin-bottom:14px;line-height:1.5}
.sp-prompt-input{width:100%;border:1px solid var(--border);border-radius:10px;padding:11px 13px;font-size:14px;font-family:inherit;box-sizing:border-box;color:var(--text);background:var(--bg2,#f8fafc)}
.sp-prompt-input:focus{border-color:var(--accent);outline:none;background:#fff}
.sp-prompt-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}
/* rev 126 (Ejaz): PHONE header (<=900) — Punch as an ICON only (a tap shows the
   labelled action to confirm), and the company switcher shows a building ICON
   in place of "GRP" (tap opens the company list). Desktop is untouched. */
@media (max-width: 900px){
  #sp-punch-btn #punch_top_lbl{display:none !important}
  #sp-punch-btn{width:38px !important;min-width:38px;padding:0 !important;justify-content:center}
  #sp-punch-btn.punch-out{background:var(--red) !important}
  /* rev 128 (Ejaz): LEFT cluster = hamburger · logo · punch · company
     (building icon + "Companies" label); RIGHT = logout · profile. The right
     group is pushed over by margin-left:auto on the logout form. Mobile only. */
  .topbar-actions{justify-content:flex-start !important;gap:8px !important}
  .topbar-actions .company{order:2;max-width:44vw}
  .topbar-actions .company .cico{font-size:0 !important}
  .topbar-actions .company .cico::before{font-family:"Font Awesome 6 Free";font-weight:900;content:"\\f1ad";font-size:13px}
  .topbar-actions .company .cname{display:block !important;font-size:13px;max-width:32vw;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .topbar-actions .company .csub,.topbar-actions .company i.fa-chevron-down{display:none !important}
  .topbar-actions #sp-punch-btn{order:1}
  .topbar-actions #sp-logout-form{order:3;margin-left:auto !important}
  .topbar-actions #sp-account-btn{order:4}
  #sp-bell-wrap{display:none !important}
  .topbar-actions .topbar-avatar{display:none !important}
}
