                scopeInput = '<div style="display:flex;gap:16px;flex-wrap:wrap;margin-bottom:14px">' + scLbl('Company', '<select id="sc-company" class="form-input" style="width:100%" onchange="scSet(&#39;company_id&#39;,this.value)">' + o + '</select>', '') + '</div>';
            } else if (ui.scope === 'state') {
