                scopeInput = '<div style="display:flex;gap:16px;flex-wrap:wrap;margin-bottom:14px">' + scLbl('State', '<select id="sc-state" class="form-input" style="width:100%" onchange="scSet(&#39;state&#39;,this.value)">' + o + '</select>', '') + '</div>';
