                scopeInput = '<div style="display:flex;gap:16px;flex-wrap:wrap;margin-bottom:14px">' + scLbl('Location (branch city)', '<select id="sc-location" class="form-input" style="width:100%" onchange="scSet(&#39;location&#39;,this.value)">' + o + '</select>', '') + '</div>';
            } else {
