        var lvTypes = (window.__LEAVE && window.__LEAVE.types && window.__LEAVE.types.length)
            ? window.__LEAVE.types
            : ['Casual Leave', 'Sick Leave', 'Earned Leave', 'Comp-Off', 'Loss of Pay'];
        var typeOpts = lvTypes.map(function (t) { return '<option>' + String(t).replace(/</g, '&lt;') + '</option>'; }).join('');
        var lbl = 'font-size:11px;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.4px;display:block;margin-bottom:4px';
        var m = document.getElementById('leave-modal') || (function () { var x = document.createElement('div'); x.id = 'leave-modal'; document.body.appendChild(x); return x; })();
        m.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:1000;display:flex;align-items:flex-start;justify-content:center;padding:40px 16px;overflow:auto';
        m.innerHTML = '<div class="card" style="max-width:640px;width:100%;padding:0">'
            + '<div style="display:flex;align-items:center;justify-content:space-between;padding:18px 22px;border-bottom:1px solid var(--border)"><h3 style="margin:0;font-size:18px">Apply Leave</h3><button class="btn btn-outline btn-sm" onclick="leaveApplyClose()"><i class="fas fa-xmark"></i></button></div>'
            + '<div style="padding:22px;display:grid;grid-template-columns:1fr 1fr;gap:14px">'
            + '<div><label style="' + lbl + '">Employee</label><select id="lv_emp" onchange="leaveBalLoad()"' + (lvSelf ? ' disabled' : '') + ' style="' + inp + (lvSelf ? ';opacity:.75;cursor:not-allowed' : '') + '">' + empOpts + '</select></div>'
            + '<div><label style="' + lbl + '">Leave Type</label><select id="lv_type" onchange="leaveBalHighlight()" style="' + inp + '">' + typeOpts + '</select></div>'
            + '<div><label style="' + lbl + '">From</label><input id="lv_from" type="date" style="' + inp + '"></div>'
            + '<div><label style="' + lbl + '">To</label><input id="lv_to" type="date" style="' + inp + '"></div>'
            + '<div style="grid-column:1/3"><label style="' + lbl + '">Reason</label><textarea id="lv_reason" rows="2" style="' + inp + '"></textarea></div>'
            + '<div style="grid-column:1/3" id="lv_balwrap"></div>'
            + '<div style="grid-column:1/3;font-size:12px;color:var(--text3)">The approver is set automatically from the employee\'s reporting manager.</div>'
            + '</div>'
            + '<div style="display:flex;gap:10px;justify-content:flex-end;padding:0 22px 20px"><button class="btn btn-outline" onclick="leaveApplyClose()">Cancel</button><button class="btn btn-primary" onclick="leaveApplySave()"><i class="fas fa-check"></i> Submit</button></div>'
            + '</div>';
        m.style.display = 'flex';
        m.onclick = function (e) { if (e.target === m) { leaveApplyClose(); } };
        if (lvSelf) { try { leaveBalLoad(); } catch (e) {} }
    };
    window.leaveApplyClose = function () { var m = document.getElementById('leave-modal'); if (m) { m.style.display = 'none'; } };
    // Load + show this employee's leave balances inside the apply modal.
    window.__leaveBal = [];
    window.leaveBalLoad = function () {
        var emp = (document.getElementById('lv_emp') || {}).value || '';
        var wrap = document.getElementById('lv_balwrap'); if (!wrap) { return; }
        if (!emp) { wrap.innerHTML = ''; window.__leaveBal = []; return; }
        wrap.innerHTML = '<div style="font-size:12px;color:var(--text3)">Loading balances…</div>';
        fetch(cfg.leaveBalancesBase + '/' + encodeURIComponent(emp), { headers: { 'X-Requested-With': 'XMLHttpRequest' }, credentials: 'same-origin' })
            .then(function (r) { return r.json(); }).then(function (j) {
                window.__leaveBal = j.rows || [];
                leaveBalRender();
            }).catch(function () { wrap.innerHTML = '<div style="font-size:12px;color:var(--red)">Could not load balances</div>'; });
    };
    function leaveBalRender() {
        var wrap = document.getElementById('lv_balwrap'); if (!wrap) { return; }
        var rows = window.__leaveBal || [];
        if (!rows.length) { wrap.innerHTML = ''; return; }
        var cur = (document.getElementById('lv_type') || {}).value || '';
        var chips = rows.map(function (b) {
            var on = b.type === cur;
            var val = b.balance === null ? 'Unlimited' : (Math.max(0, b.balance - b.pending) + ' left');
            var col = b.balance === null ? 'var(--text2)' : ((b.balance - b.pending) <= 0 ? 'var(--red)' : 'var(--green)');
            return '<div style="border:1.5px solid ' + (on ? 'var(--accent)' : 'var(--border)') + ';border-radius:9px;padding:8px 10px;min-width:120px;background:' + (on ? 'var(--accent-soft)' : '#f8fafc') + '">'
                + '<div style="font-size:11px;color:var(--text3)">' + b.type + '</div>'
                + '<div style="font-weight:700;color:' + col + '">' + val + '</div>'
                + (b.balance === null ? '' : '<div style="font-size:10px;color:var(--text3)">of ' + b.entitlement + ' · used ' + b.used + (b.pending ? ' · pending ' + b.pending : '') + '</div>')
                + '</div>';
        }).join('');
        wrap.innerHTML = '<div style="font-size:11px;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.4px;margin-bottom:6px">Balance (this year)</div><div style="display:flex;gap:8px;flex-wrap:wrap">' + chips + '</div>';
    }
    window.leaveBalHighlight = function () { leaveBalRender(); };
    window.leaveApplySave = function () {
        var g = function (id) { var e = document.getElementById(id); return e ? e.value : ''; };
        var payload = { employee: g('lv_emp'), type: g('lv_type'), from: g('lv_from'), to: g('lv_to'), reason: g('lv_reason') };
        if (!payload.employee || !payload.from || !payload.to) { if (typeof toast === 'function') { toast('Employee, From and To are required'); } return; }
        fetch(cfg.leaveApplyUrl, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': cfg.csrf, 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify(payload) })
            .then(function (r) { return r.json(); }).then(function (d) {
                if (d && d.ok) { if (typeof toast === 'function') { toast('Leave applied · approver: ' + (d.approver || 'manager')); } leaveApplyClose(); leaveLoad(); }
                else if (typeof toast === 'function') { toast((d && d.error) || 'Could not apply'); }
            }).catch(function () { if (typeof toast === 'function') { toast('Could not apply'); } });
    };
    // rev 122: themed, async replacement for window.prompt() — returns a Promise that
    // resolves to the entered string, or null if cancelled (same contract as prompt).
    window.spPrompt = function (o) {
        o = o || {};
        return new Promise(function (resolve) {
            var ov = document.createElement('div');
            ov.className = 'sp-prompt-ov';
            var okStyle = o.danger ? ' style="background:var(--red);border-color:var(--red)"' : '';
            var ph = (o.placeholder || '').replace(/"/g, '&quot;');
            var fieldHtml = o.multiline
                ? '<textarea class="sp-prompt-input" id="sp-prompt-input" rows="3" placeholder="' + ph + '"></textarea>'
                : '<input class="sp-prompt-input" id="sp-prompt-input" type="text" placeholder="' + ph + '">';
            ov.innerHTML = '<div class="sp-prompt-card" role="dialog">'
                + '<div class="sp-prompt-title">' + (o.title || '') + '</div>'
                + (o.message ? '<div class="sp-prompt-msg">' + o.message + '</div>' : '')
                + fieldHtml
                + '<div class="sp-prompt-actions">'
                + '<button class="btn btn-outline" id="sp-prompt-cancel">' + (o.cancelText || 'Cancel') + '</button>'
                + '<button class="btn btn-primary" id="sp-prompt-ok"' + okStyle + '>' + (o.okText || 'OK') + '</button>'
                + '</div></div>';
            document.body.appendChild(ov);
            var inp = ov.querySelector('#sp-prompt-input');
            if (o.value) { inp.value = o.value; }
            setTimeout(function () { try { inp.focus(); } catch (e) {} }, 30);
            var done = false;
            function close(val) { if (done) { return; } done = true; if (ov.parentNode) { ov.parentNode.removeChild(ov); } resolve(val); }
            ov.querySelector('#sp-prompt-cancel').onclick = function () { close(null); };
            ov.querySelector('#sp-prompt-ok').onclick = function () { close(inp.value); };
            ov.addEventListener('mousedown', function (e) { if (e.target === ov) { close(null); } });
            inp.addEventListener('keydown', function (e) {
                if (e.key === 'Escape') { close(null); }
                if (e.key === 'Enter' && !o.multiline) { e.preventDefault(); close(inp.value); }
            });
        });
    };
    window.leaveDecide = function (id, action) {
        var isApprove = action === 'approve';
        window.spPrompt({
            title: isApprove ? 'Approve leave' : 'Reject leave',
            message: isApprove ? 'Add an optional remark for the employee, then approve.' : 'Add an optional reason the employee will see, then reject.',
            placeholder: 'Remarks (optional)',
            okText: isApprove ? 'Approve' : 'Reject',
            danger: !isApprove,
            multiline: true
        }).then(function (remarks) {
            if (remarks === null) { return; }
            fetch(cfg.leaveDecideUrl + '/' + id + '/decide', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': cfg.csrf, 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify({ action: action, remarks: remarks }) })
                .then(function (r) { return r.json().then(function (j) { return { ok: r.ok, j: j }; }); })
                .then(function (res) {
                    if (res.ok && res.j && res.j.ok) { if (typeof toast === 'function') { toast('Leave ' + res.j.status); } leaveLoad(); window.__APPROVALS = null; }
                    else if (typeof toast === 'function') { toast((res.j && res.j.error) || 'Action failed'); }
                }).catch(function () { if (typeof toast === 'function') { toast('Action failed'); } });
        });
    };
    // ---- Approvals Inbox (real pending items awaiting the logged-in user) -----
    window.__APPROVALS = null;
    function approvalsLoad() {
        fetch(cfg.approvalsUrl, { headers: { 'X-Requested-With': 'XMLHttpRequest' }, credentials: 'same-origin' })
            .then(function (r) { return r.json(); })
            .then(function (j) { window.__APPROVALS = j; if (typeof render === 'function') { render(); } })
            .catch(function () { window.__APPROVALS = { items: [], error: 'Could not load' }; if (typeof render === 'function') { render(); } });
    }
    function approvalsInboxScreen() {
        var d = window.__APPROVALS;
        if (!d) { setTimeout(function () { if (!window.__APPROVALS) { approvalsLoad(); } }, 10); }
        if (!d) { return pghead('Approvals Inbox', 'Loading…', '') + '<div class="card"><div style="padding:40px;text-align:center;color:var(--text3)">Loading…</div></div>'; }
        if (d.error) { return pghead('Approvals Inbox', 'Error', '') + '<div class="card"><div style="padding:30px;color:var(--red)"><b>Could not load.</b><br><span style="font-size:12px;color:var(--text2)">' + String(d.error) + '</span></div></div>'; }
        var items = d.items || [];
        var scope = d.isManager ? 'Showing all pending approvals for your company.' : 'Showing items awaiting your approval.';
        if (!items.length) {
            return pghead('Approvals Inbox', scope, '') + '<div class="card"><div style="padding:44px;text-align:center;color:var(--text3)"><i class="fas fa-circle-check" style="font-size:28px;color:var(--green);margin-bottom:10px"></i><br>Nothing waiting on you. All clear.</div></div>';
        }
        var cards = items.map(function (it) {
            return '<div class="card" style="padding:16px;margin-bottom:12px;display:flex;align-items:center;gap:16px;flex-wrap:wrap">'
                + '<div style="flex:1;min-width:220px">'
                + '<div style="font-weight:700;font-size:14px">' + empNameLink(it.employee) + ' <span style="background:#eef2ff;color:#4f46e5;padding:1px 8px;border-radius:12px;font-size:11px;margin-left:6px">' + it.kind + '</span></div>'
                + '<div style="font-size:13px;color:var(--text2);margin-top:3px">' + it.detail + '</div>'
                + (it.reason ? '<div style="font-size:12px;color:var(--text3);margin-top:2px">Reason: ' + it.reason + '</div>' : '')
                + (it.approver ? '<div style="font-size:11px;color:var(--text3);margin-top:2px">Approver: ' + empNameLink(it.approver) + '</div>' : '')
                + '</div>'
                + '<div style="display:flex;gap:8px"><button class="btn btn-primary btn-sm" onclick="inboxDecide(\'' + (it.module || 'leave') + '\',' + it.id + ',\'approve\')"><i class="fas fa-check"></i> Approve</button>'
                + '<button class="btn btn-outline btn-sm" style="color:var(--red)" onclick="inboxDecide(\'' + (it.module || 'leave') + '\',' + it.id + ',\'reject\')"><i class="fas fa-xmark"></i> Reject</button></div>'
                + '</div>';
        }).join('');
        return pghead('Approvals Inbox', d.count + ' item(s) pending · ' + scope, '') + cards;
    }
    // ---- Generic money/HR request modules (real DB + hierarchy approval) ------
    // Maps a nav id → backend module key + apply-form fields. amount:true adds an
    // Amount input used for the approver threshold rule.
    var RQ_MAP = {
        'expenses': { m: 'expenses', title: 'Expense Claims', amount: true, fields: [{ k: 'type', l: 'Type', opts: ['Travel', 'Fuel', 'Conveyance', 'Mobile/Data', 'Other'] }, { k: 'reason', l: 'Note' }] },
        'advance': { m: 'advances', title: 'Salary Advance', amount: true, fields: [{ k: 'reason', l: 'Reason' }] },
        'loans': { m: 'loans', title: 'Loans & Advances', amount: true, fields: [{ k: 'emi', l: 'EMI (₹)', t: 'number' }, { k: 'tenure_months', l: 'Tenure (months)', t: 'number' }, { k: 'reason', l: 'Purpose' }] },
        'commissions': { m: 'commissions', title: 'Commission Entries', single: 'Commission Entry', amount: true, amountRO: 'Net Payable (₹) — auto: Gross − TDS', fields: [
            // rev 116d: TWO claim types — collection (evidence + accounts stage)
            // vs simple (target/bonus, manager approval only).
            { k: 'claim_type', l: 'Claim Type', opts: ['Collection claim — money collected from a customer', 'Simple claim — target / bonus / special incentive'], oninput: 'commClaimTypeToggle()' },
            { k: 'purpose', l: 'Purpose', opts: ['EMI Collection', 'Settlement / OTS', 'Recovery Incentive', 'Penalty Collection', 'Repo / Seizure', 'Target Bonus', 'Field Visit Allowance', 'Other'] },
            { k: 'cycle_month', l: 'For Month', t: 'month' },
            { k: 'customer_name', l: 'Customer Name' },
            { k: 'account_ref', l: 'Account No / CC No / Customer ID' },
            { k: 'collection_type', l: 'What Was Collected', opts: ['EMI', 'Penalty', 'Settlement / OTS', 'Part-payment', 'Multiple', 'Other'] },
            { k: 'collected_at', l: 'Collected On (date & time)', t: 'datetime-local' },
            { k: 'collection_location', l: 'Collection Location' },
            { k: 'collection_mode', l: 'Mode of Collection', opts: ['Cash — submitted to office', 'Cash — deposited to bank', 'Client paid company directly', 'Online to company account'] },
            { k: 'portfolio', l: 'Portfolio / Bank' },
            // rev 116c (Ejaz): TWO clearly-named amounts — what the CUSTOMER paid
            // vs what the AGENT is claiming as commission.
            { k: 'base_amount', l: 'Amount Collected from Customer (₹)', t: 'number', oninput: 'schemeBaseCalc()' },
            { k: 'gross_amount', l: 'Commission Claimed — Gross (₹), before TDS', t: 'number', oninput: 'rqCommCalc()' },
            { k: 'tds_rate', l: 'TDS % (194H)', t: 'number', oninput: 'rqCommCalc()', defRate: 1 },
            { k: 'payout_date', l: 'Payout Date (decides which payslip pays it)', t: 'date' },
            { k: 'payout_method', l: 'Payout Method', opts: ['With salary (in the payslip)', 'Separate payout (own dates - ledger)'] },
            { k: 'description', l: 'Short Description' },
            { k: 'scheme_id', hidden: 1 },
            { k: 'proof_path', hidden: 1 }] },
        'clawbacks': { m: 'clawbacks', title: 'Clawbacks / Reversals', amount: true, fields: [{ k: 'portfolio', l: 'Portfolio' }, { k: 'cycle_month', l: 'Month' }, { k: 'reason', l: 'Reason' }] },
        'increments': { m: 'increments', title: 'Increment / Appraisal', single: 'Increment / Appraisal', amount: false, fields: [
            { k: 'cycle', l: 'Cycle', opts: ['Annual', 'Half-yearly', 'Quarterly', 'Promotion', 'Special / Market correction', 'Confirmation'] },
            { k: 'old_ctc', l: 'Old CTC (₹) — auto from record', t: 'number', oninput: 'rqIncCalc(0)' },
            { k: 'new_ctc', l: 'New CTC (₹)', t: 'number', oninput: 'rqIncCalc(0)' },
            { k: 'pct', l: '% Increase (type either this or New CTC)', t: 'number', oninput: 'rqIncCalc(1)' },
            { k: 'new_designation', l: 'New Designation (promotion — optional)' },
            { k: 'effective', l: 'Effective Date', t: 'date' },
            { k: 'reason', l: 'Reason / Justification' }] },
        'exits': { m: 'exits', title: 'Exit & FnF', amount: false, fields: [{ k: 'last_working_day', l: 'Last Working Day', t: 'date' }, { k: 'reason', l: 'Reason' }, { k: 'id_surrendered', l: 'ID card surrendered', opts: ['Yes', 'No', 'N/A'] }, { k: 'access_revoked', l: 'System / portal access revoked', opts: ['Yes', 'No', 'N/A'] }, { k: 'dra_id_returned', l: 'DRA / authorisation ID returned', opts: ['Yes', 'No', 'N/A'] }, { k: 'data_handed_over', l: 'Borrower data / files handed over', opts: ['Yes', 'No', 'N/A'] }, { k: 'knowledge_transfer', l: 'Knowledge transfer done', opts: ['Yes', 'No', 'Pending'] }, { k: 'final_clearance', l: 'Final clearance', opts: ['Cleared', 'Withheld', 'Pending'] }, { k: 'cleared_by', l: 'Cleared By' }, { k: 'cleared_on', l: 'Cleared On', t: 'date' }, { k: 'clearance_remarks', l: 'Clearance Remarks' }] },
        'bonus-enc': { m: 'bonus', title: 'Bonus & Encashment', amount: true, fields: [{ k: 'kind', l: 'Type', opts: ['Statutory Bonus', 'Festival Bonus', 'Leave Encashment'] }] },
        'transfers': { m: 'transfers', title: 'Employee Transfers', amount: false, fields: [
            { k: 'type', l: 'Transfer Type', opts: ['Branch transfer', 'Department transfer', 'Company transfer'] },
            { k: 'to_company', l: 'To Company (company transfer)' },
            { k: 'to_branch', l: 'To Branch' },
            { k: 'to_department', l: 'To Department (dept. transfer)' },
            { k: 'effective_date', l: 'Effective Date', t: 'date' },
            { k: 'reason', l: 'Reason' }] }
    };
    window.__REQ = {};
    window.__REQFY = {};
    function requestLoad(navId) {
        var cfg2 = RQ_MAP[navId]; if (!cfg2) { return; }
        var fy = window.__REQFY[navId] || '';
        var url = cfg.requestsBase + '/' + cfg2.m + (fy && fy !== 'all' ? ('?fy=' + encodeURIComponent(fy)) : '');
        fetch(url, { headers: { 'X-Requested-With': 'XMLHttpRequest' }, credentials: 'same-origin' })
            .then(function (r) { return r.json(); })
            .then(function (j) { window.__REQ[navId] = j; if (typeof render === 'function') { render(); } })
            .catch(function () { window.__REQ[navId] = { rows: [], error: 'Could not load' }; if (typeof render === 'function') { render(); } });
    }
    window.reqSetFy = function (navId, fy) { window.__REQFY[navId] = fy; requestLoad(navId); };
    // ---- rev 78: Transfer PROCESS TRACKER (per-row expandable stage pipeline) -
    window.trTrack = function (id) { var x = document.getElementById('tr-track-' + id); if (x) { x.style.display = x.style.display === 'none' ? '' : 'none'; } };
    function trStep(state, label, sub) {
        var col = state === 'done' ? '#16a34a' : (state === 'fail' ? '#b91c1c' : (state === 'prog' ? '#f59e0b' : '#cbd5e1'));
        var icon = state === 'done' ? '&#10003;' : (state === 'fail' ? '&#10005;' : (state === 'prog' ? '&#8226;' : '&#9675;'));
        return '<div style="display:flex;flex-direction:column;align-items:center;min-width:104px">'
            + '<div style="width:26px;height:26px;border-radius:50%;background:' + col + ';color:#fff;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;flex:none">' + icon + '</div>'
            + '<div style="font-size:11.5px;font-weight:700;margin-top:5px;color:var(--text2);text-align:center">' + label + '</div>'
            + (sub ? '<div style="font-size:10.5px;color:var(--text3);text-align:center;max-width:130px">' + sub + '</div>' : '')
            + '</div>';
    }
    function trConn(done) { return '<div style="flex:1;height:2px;background:' + (done ? '#16a34a' : '#e2e8f0') + ';margin-top:13px;min-width:16px"></div>'; }
    function trTrackRow(r, span) {
        var t = r.timeline || {};
        var steps = [];
        steps.push(['done', 'Raised', t.raisedAt || '']);
        if (r.status === 'Rejected') { steps.push(['fail', 'Rejected', (r.decidedBy || '') + (r.decidedAt ? ' &middot; ' + r.decidedAt : '')]); }
        else if (r.status === 'Pending') { steps.push(['todo', 'Approval', 'awaiting ' + (r.approver || 'manager')]); }
        else { steps.push(['done', 'Approved', (r.decidedBy || '') + (r.decidedAt ? ' &middot; ' + r.decidedAt : '')]); }
        if (r.status !== 'Rejected') {
            steps.push([t.orderSentAt ? 'done' : 'todo', 'Letter emailed', t.orderSentAt || (r.status === 'Pending' ? 'after approval' : '')]);
            steps.push([t.acceptedAt ? 'done' : 'todo', 'Acknowledged', t.acceptedAt || 'awaiting employee']);
            steps.push([t.appliedAt ? 'done' : 'todo', 'Applied', t.appliedAt || (r.status === 'Approved' ? 'on ' + (t.effectiveDate || 'effective date') : '')]);
            if ((t.type || '').toLowerCase().indexOf('compan') >= 0) {
                var ob = t.onboarding || '';
                steps.push([ob === 'completed' ? 'done' : (ob ? 'prog' : 'todo'), 'Onboarding', ob === 'completed' ? 'formalities complete' : (ob ? 'formalities in progress' : 'starts on apply')]);
            }
        }
        var h = '';
        for (var i = 0; i < steps.length; i++) {
            if (i > 0) { h += trConn(steps[i - 1][0] === 'done'); }
            h += trStep(steps[i][0], steps[i][1], steps[i][2]);
        }
        return '<tr id="tr-track-' + r.id + '" style="display:none"><td colspan="' + span + '" style="background:#f8fafc;border-top:1px solid var(--border);padding:16px 22px"><div style="display:flex;align-items:flex-start;overflow:auto">' + h + '</div></td></tr>';
    }
    function requestScreen(navId) {
        var rc = RQ_MAP[navId];
        var d = window.__REQ[navId];
        if (!d) { setTimeout(function () { if (!window.__REQ[navId]) { requestLoad(navId); } }, 10); }
        var addBtn = '<button class="btn btn-primary" onclick="reqApplyOpen(\'' + navId + '\')"><i class="fas fa-plus"></i> New ' + (rc.single || rc.title.replace(/s$/, '')) + '</button>';
        if (navId === 'commissions') {
            addBtn = '<button class="btn btn-outline" onclick="commLedgerOpen()"><i class="fas fa-book"></i> Ledger</button> <button class="btn btn-outline" onclick="commBulkOpen()"><i class="fas fa-file-import"></i> Upload Excel / CSV</button> <button class="btn btn-outline" onclick="go(\'commission-calc\')"><i class="fas fa-calculator"></i> Calculator</button> ' + addBtn;
            // rev 85c: orphan cleaner appears only when orphans are on screen.
            try {
                if ((cfg.role === 'Admin' || cfg.role === 'Super Admin') && d && (d.rows || []).some(function (x) { return String(x.employee || '').indexOf('no longer exists') >= 0; })) {
                    addBtn = '<button class="btn btn-outline" style="color:var(--red)" onclick="commCleanOrphans()" title="Remove entries whose employee record was wiped by an old demo reset"><i class="fas fa-broom"></i> Clean orphaned entries</button> ' + addBtn;
                }
            } catch (e) {}
        }
        var fyOpts = (d && d.fyOptions) || [];
        if (fyOpts.length) { var curFy = window.__REQFY[navId] || 'all'; addBtn = '<select onchange="reqSetFy(\'' + navId + '\',this.value)" style="padding:8px 10px;border:1.5px solid var(--border);border-radius:9px;font-size:13px;background:#fff;margin-right:10px"><option value="all"' + (curFy === 'all' ? ' selected' : '') + '>All years</option>' + fyOpts.map(function (fy) { return '<option value="' + fy + '"' + (curFy === fy ? ' selected' : '') + '>FY ' + fy + '</option>'; }).join('') + '</select>' + addBtn; }
        if (!d) { return pghead(rc.title, 'Loading…', addBtn) + '<div class="card"><div style="padding:40px;text-align:center;color:var(--text3)">Loading…</div></div>'; }
        if (d.error) { return pghead(rc.title, 'Error', addBtn) + '<div class="card"><div style="padding:30px;color:var(--red)"><b>Could not load.</b><br><span style="font-size:12px;color:var(--text2)">' + String(d.error) + '</span></div></div>'; }
        var rows = d.rows || [];
        var cols = ['Employee'].concat(rc.amount ? [rc.amountRO ? 'Net Payable' : 'Amount'] : []).concat(['Details', 'Approver', 'Status', 'Decided By', 'Action']);
        var th = cols.map(function (h) { return '<th style="padding:10px 12px;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.4px;color:var(--text3);white-space:nowrap">' + h + '</th>'; }).join('');
        var dash = '<span style="color:var(--text3)">—</span>';
        var body = rows.map(function (r) {
            var c = 'padding:9px 12px;font-size:13px;border-top:1px solid var(--border);white-space:nowrap';
            var act = r.canDecide
                ? '<button class="btn btn-sm btn-primary" onclick="reqDecide(\'' + rc.m + '\',' + r.id + ',\'approve\')">Approve</button> <button class="btn btn-sm btn-outline" style="color:var(--red)" onclick="reqDecide(\'' + rc.m + '\',' + r.id + ',\'reject\')">Reject</button>'
                : (r.decidedBy ? '<span style="font-size:11px;color:var(--text3)">' + r.decidedBy + (r.decidedAt ? ' · ' + r.decidedAt : '') + '</span>' : dash);
            if (navId === 'transfers' && (r.status === 'Approved' || r.status === 'Applied')) {
                act += ' <a href="' + cfg.transfersBase + '/' + r.id + '/letter" target="_blank" title="Transfer Order (PDF)"><i class="fas fa-file-pdf" style="color:var(--red);margin-left:6px"></i></a>';
            }
            if (navId === 'transfers') {
                act += ' <a onclick="trTrack(' + r.id + ')" style="font-size:11px;cursor:pointer;color:var(--accent);font-weight:700;margin-left:8px">Track</a>';
            }
            // rev 84 (Ejaz, USP): commission lifecycle controls. LOCKED = frozen;
            // otherwise managers can Edit (even after approval) or Reopen an
            // approved entry; Admin can Lock manually. History always available.
            if (navId === 'commissions') {
                act += ' <a onclick="commHist(' + r.id + ')" title="Full history of this entry" style="cursor:pointer;color:#4f46e5;font-size:12px;margin-left:8px;white-space:nowrap"><i class="fas fa-clock-rotate-left"></i> History</a>';
                // rev181 — BOUNCE: chip when bounced; one-click action for Accounts/managers.
                if (r.bounced) {
                    act += ' <span title="' + (r.bounceReason || '') + (r.bounceClawbackId ? ' - clawback #' + r.bounceClawbackId : '') + '" style="background:#fee2e2;color:#991b1b;font-size:10px;font-weight:800;padding:2px 8px;border-radius:99px;margin-left:8px;white-space:nowrap"><i class="fas fa-rotate-left"></i> BOUNCED</span>';
                } else if ((d.canAccounts || d.isManager) && r.status !== 'Rejected') {
                    act += ' <a onclick="commBounce(' + r.id + ')" title="Cheque returned / settlement cancelled - creates an approved clawback automatically if this was already paid" style="cursor:pointer;color:#b91c1c;font-size:12px;margin-left:8px;white-space:nowrap"><i class="fas fa-rotate-left"></i> Bounce</a>';
                }
                // rev 116: collection evidence — proof link + ACCOUNTS stage chip
                // + Confirm/Flag actions for the Accounts role.
                if (r.hasProof) {
                    act += ' <a href="' + cfg.requestsBase + '/commissions/' + r.id + '/proof" target="_blank" rel="noopener" title="View the payment proof"><i class="fas fa-receipt" style="color:#0891b2;margin-left:8px"></i></a>';
                }
                if (r.accountsStatus === 'pending') {
                    act += ' <span style="background:#fef3c7;color:#92400e;font-size:10px;font-weight:800;padding:2px 8px;border-radius:99px;margin-left:8px;white-space:nowrap"><i class="fas fa-hourglass-half"></i> ACCOUNTS PENDING</span>';
                } else if (r.accountsStatus === 'confirmed') {
                    act += ' <span title="' + (r.accountsBy || '') + '" style="background:#dcfce7;color:#15803d;font-size:10px;font-weight:800;padding:2px 8px;border-radius:99px;margin-left:8px;white-space:nowrap"><i class="fas fa-check"></i> ACCOUNTS OK</span>';
                } else if (r.accountsStatus === 'flagged') {
                    act += ' <span title="' + (r.accountsNote || '') + '" style="background:#fee2e2;color:#991b1b;font-size:10px;font-weight:800;padding:2px 8px;border-radius:99px;margin-left:8px;white-space:nowrap"><i class="fas fa-flag"></i> ACCOUNTS FLAGGED</span>';
                }
                if (d.canAccounts && (r.accountsStatus === 'pending' || r.accountsStatus === 'flagged') && !r.locked) {
                    act += ' <a onclick="commAccounts(' + r.id + ',&#39;confirm&#39;)" title="Confirm the money was received" style="cursor:pointer;color:#15803d;font-size:12px;margin-left:8px;white-space:nowrap;font-weight:700"><i class="fas fa-check-double"></i> Confirm</a>';
                    if (r.accountsStatus === 'pending') {
                        act += ' <a onclick="commAccounts(' + r.id + ',&#39;flag&#39;)" title="Flag a problem with this collection" style="cursor:pointer;color:#b91c1c;font-size:12px;margin-left:8px;white-space:nowrap"><i class="fas fa-flag"></i> Flag</a>';
                    }
                }
                // rev 85: disbursement — Record payment on approved SEPARATE
                // entries with balance; paid/partial chip for everyone.
                if (r.paidTotal > 0) {
                    var full = r.balance != null && r.balance <= 0.005;
                    act += ' <span style="background:' + (full ? '#dcfce7;color:#15803d' : '#fef9c3;color:#a16207') + ';font-size:10px;font-weight:800;padding:2px 8px;border-radius:99px;margin-left:8px;white-space:nowrap">' + (full ? 'PAID ' + inr(r.paidTotal) : 'PART-PAID ' + inr(r.paidTotal) + ' / bal ' + inr(r.balance)) + '</span>';
                }
                if (!r.locked && d.isManager && r.status === 'Approved' && r.payoutMethod === 'separate' && (r.balance == null || r.balance > 0.005)) {
                    act += ' <a onclick="commPay(' + r.id + ')" title="Record a payment (partial allowed)" style="cursor:pointer;color:#15803d;font-size:12px;margin-left:8px;white-space:nowrap;font-weight:700"><i class="fas fa-money-bill-wave"></i> Record payment</a>';
                }
                if (r.locked) {
                    act += ' <span title="' + (r.lockSource || 'locked') + '" style="background:#e2e8f0;color:#334155;font-size:10px;font-weight:800;padding:2px 8px;border-radius:99px;margin-left:8px;white-space:nowrap"><i class="fas fa-lock"></i> LOCKED</span>';
                } else if (d.isManager) {
                    act += ' <a onclick="commEdit(' + r.id + ')" title="Edit this entry (every change is recorded)" style="cursor:pointer;color:#0891b2;font-size:12px;margin-left:8px;white-space:nowrap"><i class="fas fa-pen"></i> Edit</a>';
                    if (r.status === 'Approved') {
                        act += ' <a onclick="commReopen(' + r.id + ')" title="Send back to Pending for re-decision" style="cursor:pointer;color:#d97706;font-size:12px;margin-left:8px;white-space:nowrap"><i class="fas fa-rotate-left"></i> Reopen</a>';
                    }
                    if (cfg.role === 'Admin' || cfg.role === 'Super Admin') {
                        act += ' <a onclick="commLock(' + r.id + ')" title="Lock — freeze this entry forever" style="cursor:pointer;color:#334155;font-size:12px;margin-left:8px;white-space:nowrap"><i class="fas fa-lock"></i> Lock</a>';
                    }
                }
            }
            // rev 83b/84b: increments — View always; Edit until APPLIED;
            // Delete only BEFORE approval (Ejaz's rule); letter + apply.
            if (navId === 'increments') {
                act += ' <a onclick="incView(' + r.id + ')" title="View full details" style="cursor:pointer;color:#4f46e5;font-size:12px;margin-left:8px;white-space:nowrap"><i class="fas fa-eye"></i> View</a>';
                if (d.isManager && !r.appliedAt) {
                    act += ' <a onclick="incEdit(' + r.id + ')" title="Edit this increment" style="cursor:pointer;color:#0891b2;font-size:12px;margin-left:8px;white-space:nowrap"><i class="fas fa-pen"></i> Edit</a>';
                    if (r.status !== 'Approved') {
                        act += ' <a onclick="incDel(' + r.id + ')" title="Delete (only possible before approval)" style="cursor:pointer;color:var(--red);font-size:12px;margin-left:8px;white-space:nowrap"><i class="fas fa-trash"></i> Delete</a>';
                    }
                }
            }
            if (navId === 'increments' && r.status === 'Approved') {
                act += ' <a href="' + cfg.incrementsBase + '/' + r.id + '/letter" target="_blank" rel="noopener" title="Increment Letter (PDF)"><i class="fas fa-file-pdf" style="color:var(--red);margin-left:6px"></i></a>';
                if (r.appliedAt) { act += ' <span style="font-size:11px;color:#16a34a;font-weight:700;margin-left:8px" title="by ' + (r.appliedBy || 'HR') + '"><i class="fas fa-check"></i> Applied ' + r.appliedAt + '</span>'; }
                else if (d.isManager) { act += ' <button class="btn btn-sm btn-outline" style="margin-left:8px" onclick="incApply(' + r.id + ')" title="Update the employee record to the new CTC (and designation)">Apply to record</button>'; }
            }
            var amtCell = rc.amount ? ('<td style="' + c + '">' + (r.amount != null ? inr(r.amount) : dash) + '</td>') : '';
            var rowHtml = '<tr>'
                + '<td style="' + c + ';font-weight:600">' + empNameLink(r.employee, r.empCode || r.employee) + (r.empCode ? ' <span style="color:var(--text3);font-weight:400">(' + r.empCode + ')</span>' : '') + '</td>'
                + amtCell
                + '<td style="' + c + ';white-space:normal;min-width:240px;max-width:430px;line-height:1.5">' + (r.extra || r.reason || dash) + '</td>'
                + '<td style="' + c + '">' + (r.approver ? empNameLink(r.approver) : dash) + '</td>'
                + '<td style="' + c + '">' + leaveBadge(r.status) + '</td>'
                + '<td style="' + c + '">' + (r.decidedBy ? empNameLink(r.decidedBy) : dash) + '</td>'
                + '<td style="' + c + '">' + act + '</td>'
                + '</tr>';
            if (navId === 'transfers' && r.timeline) { rowHtml += trTrackRow(r, cols.length); }
            return rowHtml;
        }).join('');
        var pend = rows.filter(function (r) { return r.status === 'Pending'; }).length;
        return pghead(rc.title, rows.length + ' record(s) · ' + pend + ' pending · approver set from each employee\'s reporting manager' + (rc.amount ? ' (large amounts escalate one level)' : ''), addBtn)
            + '<div class="card" style="padding:0;overflow:auto"><table style="width:100%;border-collapse:collapse"><thead><tr>' + th + '</tr></thead><tbody>'
            + (rows.length ? body : '<tr><td colspan="' + cols.length + '" style="padding:36px;text-align:center;color:var(--text3)">No records yet. Click the button above to create one.</td></tr>')
            + '</tbody></table></div>';
    }
    window.reqApplyOpen = function (navId) {
        var rc = RQ_MAP[navId]; if (!rc) { return; }
        var emps = ((typeof DB !== 'undefined' && DB.employees) || []).map(function (e) { return e.name; });
        var inp = 'width:100%;padding:9px 11px;border:1.5px solid var(--border);border-radius:9px;font-size:14px;background:#f8fafc;font-family:var(--font2)';
        var lbl = 'font-size:11px;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.4px;display:block;margin-bottom:4px';
        var f = '<div><label style="' + lbl + '">Employee</label><select id="rq_emp" style="' + inp + '"><option value="">Select employee…</option>' + emps.map(function (n) { return '<option>' + n + '</option>'; }).join('') + '</select></div>';
        // rev 83: amountRO = the amount is COMPUTED (commission net = gross − TDS),
        // shown read-only and placed AFTER the inputs that drive it.
        var amountHtml = rc.amount ? '<div><label style="' + lbl + '">' + (rc.amountRO || 'Amount (₹)') + '</label><input id="rq_amount" type="number"' + (rc.amountRO ? ' readonly tabindex="-1"' : '') + ' style="' + inp + (rc.amountRO ? ';background:#eef2f7;color:var(--text2);font-weight:700' : '') + '"></div>' : '';
        if (rc.amount && !rc.amountRO) { f += amountHtml; }
        rc.fields.forEach(function (fl) {
            // rev 115: hidden carrier fields (scheme_id / base_amount) — collected
            // by the generic saver but never shown to the user.
            if (fl.hidden) { f += '<input type="hidden" id="rqf_' + fl.k + '">'; return; }
            var extraAttr = fl.oninput ? ' oninput="' + fl.oninput + '"' : '';
            var defVal = '';
            if (fl.defRate) { defVal = '5'; try { var rr = spRates(); if (rr && rr.comm_tds_rate != null) { defVal = String(rr.comm_tds_rate); } } catch (e) {} }
            else if (fl.t === 'month') { try { defVal = new Date().toISOString().slice(0, 7); } catch (e) {} }
            else if (fl.k === 'payout_date') {
                // rev181c (D4) — the tenant payout lag pre-fills the payout date
                // (1st of earned month + N); fully editable before submitting.
                try {
                    var lg0 = Number((spRates() || {}).incentive_payout_lag) || 0;
                    if (lg0 > 0) {
                        var dt0 = new Date(); dt0.setDate(1); dt0.setMonth(dt0.getMonth() + lg0);
                        var mm0 = dt0.getMonth() + 1;
                        defVal = dt0.getFullYear() + '-' + (mm0 < 10 ? '0' + mm0 : mm0) + '-01';
                    }
                } catch (e) {}
            }
            var ctrl = fl.opts ? ('<select id="rqf_' + fl.k + '" style="' + inp + '"' + extraAttr + '>' + fl.opts.map(function (o) { return '<option>' + o + '</option>'; }).join('') + '</select>')
                : ('<input id="rqf_' + fl.k + '" type="' + (fl.t || 'text') + '" value="' + defVal + '" style="' + inp + '"' + extraAttr + '>');
            f += '<div><label style="' + lbl + '">' + fl.l + '</label>' + ctrl + '</div>';
        });
        if (rc.amount && rc.amountRO) { f += amountHtml; }
        var m = document.getElementById('req-modal') || (function () { var x = document.createElement('div'); x.id = 'req-modal'; document.body.appendChild(x); return x; })();
        m.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:1000;display:flex;align-items:flex-start;justify-content:center;padding:40px 16px;overflow:auto';
        m.innerHTML = '<div class="card" style="max-width:640px;width:100%;padding:0">'
            + '<div style="display:flex;align-items:center;justify-content:space-between;padding:18px 22px;border-bottom:1px solid var(--border)"><h3 style="margin:0;font-size:18px">New ' + (rc.single || rc.title.replace(/s$/, '')) + '</h3><button class="btn btn-outline btn-sm" onclick="reqApplyClose()"><i class="fas fa-xmark"></i></button></div>'
            + '<div style="padding:22px;display:grid;grid-template-columns:1fr 1fr;gap:14px">' + f
            + '<div style="grid-column:1/3;font-size:12px;color:var(--text3)">The approver is set automatically from the employee\'s reporting manager' + (rc.amount ? '; amounts over the limit escalate one level up.' : '.') + '</div></div>'
            + '<div style="display:flex;gap:10px;justify-content:flex-end;padding:0 22px 20px"><button class="btn btn-outline" onclick="reqApplyClose()">Cancel</button><button class="btn btn-primary" onclick="reqApplySave(\'' + navId + '\')"><i class="fas fa-check"></i> Submit</button></div>'
            + '</div>';
        m.style.display = 'flex';
        m.onclick = function (e) { if (e.target === m) { reqApplyClose(); } };
    };
    window.reqApplyClose = function () { var m = document.getElementById('req-modal'); if (m) { m.style.display = 'none'; } };
    // rev 83: live net = gross − TDS% for the commission entry modal.
    window.rqCommCalc = function () {
        var g = Number((document.getElementById('rqf_gross_amount') || {}).value || 0);
        var rEl = document.getElementById('rqf_tds_rate');
        var rt = (rEl && rEl.value !== '') ? Number(rEl.value) : 5;
        if (!(rt >= 0 && rt <= 100)) { rt = 5; }
        var net = g > 0 ? Math.round((g - (g * rt / 100)) * 100) / 100 : 0;
        var a = document.getElementById('rq_amount'); if (a) { a.value = net > 0 ? net : ''; }
    };
    // ---- rev 119: MOBILE DEVICES approval screen -----------------------------
    window.__MOBDEV = null;
    function mobDevLoad() {
        fetch(cfg.mobileDevBase + '/list', { headers: { 'X-Requested-With': 'XMLHttpRequest' }, credentials: 'same-origin' })
            .then(function (r) { return r.json(); })
            .then(function (j) { window.__MOBDEV = j; if (typeof render === 'function') { render(); } })
            .catch(function () { window.__MOBDEV = { rows: [], error: 'Could not load' }; if (typeof render === 'function') { render(); } });
    }
    function mobDevChip(st) {
        var m = { pending: ['#fef3c7', '#92400e', 'PENDING'], approved: ['#dcfce7', '#166534', 'APPROVED'], rejected: ['#fee2e2', '#991b1b', 'REJECTED'] };
        var c = m[st] || m.pending;
        return '<span style="background:' + c[0] + ';color:' + c[1] + ';font-size:11px;font-weight:700;padding:3px 10px;border-radius:99px">' + c[2] + '</span>';
    }
    function mobileDevicesScreen() {
        var d = window.__MOBDEV;
        if (!d) { setTimeout(function () { if (!window.__MOBDEV) { mobDevLoad(); } }, 10); return pghead('Mobile Devices', 'Loading…', '') + '<div class="card"><div style="padding:40px;text-align:center;color:var(--text3)">Loading devices…</div></div>'; }
        var rows = d.rows || [];
        var body = rows.map(function (x) {
            var act = '';
            if (x.status === 'pending' || x.status === 'rejected') {
                act += '<button class="btn btn-primary btn-sm" onclick="mobDevDecide(' + x.id + ',&#39;approve&#39;)"><i class="fas fa-check"></i> Approve</button> ';
            }
            if (x.status === 'pending') {
                act += '<button class="btn btn-outline btn-sm" onclick="mobDevDecide(' + x.id + ',&#39;reject&#39;)" style="color:var(--red)">Reject</button>';
            }
            if (x.status === 'approved') {
                act += '<button class="btn btn-outline btn-sm" onclick="mobDevDecide(' + x.id + ',&#39;revoke&#39;)" style="color:var(--red)"><i class="fas fa-ban"></i> Revoke</button>';
            }
            return '<tr>'
                + '<td><b>' + (x.deviceName || 'Mobile device') + '</b><div style="font-size:11px;color:var(--text3)">' + (x.platform || '') + (x.host ? ' · ' + x.host : '') + (x.hasPush ? ' · <i class="fas fa-bell" title="push enabled"></i>' : '') + '</div></td>'
                + '<td><span style="font-family:monospace;font-size:13px;background:#f1f5f9;padding:2px 8px;border-radius:6px">' + (x.code || '—') + '</span></td>'
                + '<td style="font-size:12.5px;color:var(--text2)">' + (x.registered || '') + (x.lastSeen ? '<div style="font-size:11px;color:var(--text3)">seen ' + x.lastSeen + '</div>' : '') + '</td>'
                + '<td>' + mobDevChip(x.status) + (x.status === 'approved' && x.approvedBy ? '<div style="font-size:11px;color:#166534">by ' + x.approvedBy + '</div>' : '') + (x.status === 'rejected' && x.rejectReason ? '<div style="font-size:11px;color:#991b1b">' + x.rejectReason + '</div>' : '') + '</td>'
                + '<td style="white-space:nowrap">' + act + '</td>'
                + '</tr>';
        }).join('');
        return pghead('Mobile Devices', 'Approve the phones that may use the SmartPRS app. Only an approved device can sign in and punch — revoke a lost phone to lock it out instantly.', '<button class="btn btn-outline" onclick="window.__MOBDEV=null;mobDevLoad()"><i class="fas fa-rotate"></i> Refresh</button>')
            + '<div class="card" style="padding:0;overflow-x:auto"><table class="tbl" style="width:100%"><thead><tr><th>Device</th><th>Code</th><th>Registered</th><th>Status</th><th></th></tr></thead><tbody>'
            + (body || '<tr><td colspan="5" style="text-align:center;color:var(--text3);padding:34px">No devices yet. When an employee enters your web address in the SmartPRS app, their phone appears here for approval.</td></tr>')
            + '</tbody></table></div>';
    }
    window.mobDevDecide = function (id, action) {
        var body = {};
        if (action === 'reject') {
            var reason = window.prompt('Reason for rejecting (the phone shows this):', '');
            if (reason === null) { return; }
            body.reason = reason;
        } else if (action === 'revoke') {
            if (!window.confirm('Revoke this device? It loses access on its next check (use for a lost/stolen phone).')) { return; }
            action = 'revoke'; body.reason = 'Access revoked by your administrator.';
        } else if (!window.confirm('Approve this device? It unlocks on the phone within a few seconds.')) { return; }
        fetch(cfg.mobileDevBase + '/' + id + '/' + action, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': cfg.csrf, 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify(body) })
            .then(function (r) { return r.json(); })
            .then(function (j) {
                if (j && j.ok) { if (typeof toast === 'function') { toast(j.message || 'Done'); } window.__MOBDEV = null; mobDevLoad(); }
                else if (typeof toast === 'function') { toast((j && j.error) || 'Action failed'); }
            }).catch(function () {});
    };
    // ---- rev 115: COMMISSION & INCENTIVE SCHEMES screen ----------------------
    window.__SCHEMES = null;
    function schemesLoad() {
        fetch(cfg.schemesBase, { headers: { 'X-Requested-With': 'XMLHttpRequest' }, credentials: 'same-origin' })
            .then(function (r) { return r.json(); })
            .then(function (j) { window.__SCHEMES = j; if (typeof render === 'function') { render(); } })
            .catch(function () { window.__SCHEMES = { rows: [], error: 'Could not load' }; if (typeof render === 'function') { render(); } });
    }
    function schemeStateChip(st) {
        var map = { active: ['#dcfce7', '#166534', 'ACTIVE'], upcoming: ['#dbeafe', '#1d4ed8', 'UPCOMING'], expired: ['#f1f5f9', '#64748b', 'EXPIRED'], withdrawn: ['#fee2e2', '#991b1b', 'WITHDRAWN'], pending: ['#fef3c7', '#92400e', 'PENDING APPROVAL'], rejected: ['#fee2e2', '#991b1b', 'REJECTED'] };
        var c = map[st] || map.expired;
        return '<span style="background:' + c[0] + ';color:' + c[1] + ';font-size:11px;font-weight:700;padding:3px 10px;border-radius:99px">' + c[2] + '</span>';
    }
    // rev 115g: full detail view — creation + approval trail + claims.
    window.schemeView = function (id) {
        var rows = (window.__SCHEMES && window.__SCHEMES.rows) || [];
        var s = rows.find(function (x) { return String(x.id) === String(id); });
        if (!s) { return; }
        var row = function (a, b) { return '<div style="display:flex;justify-content:space-between;gap:14px;padding:7px 0;border-bottom:1px solid var(--border);font-size:13.5px"><span style="color:var(--text3)">' + a + '</span><b style="text-align:right">' + (b || '—') + '</b></div>'; };
        var trail = row('Created by', (s.createdBy || '') + (s.createdAt ? ' · ' + s.createdAt : ''));
        if (s.approvalStatus === 'pending') { trail += row('Approval', 'PENDING — awaiting ' + (s.approver || 'Admin / HR')); }
        else if (s.approvalStatus === 'rejected') { trail += row('Approval', 'REJECTED by ' + (s.decidedBy || '') + (s.decidedAt ? ' · ' + s.decidedAt : '') + (s.rejectReason ? '<br>' + s.rejectReason : '')); }
        else { trail += row('Approval', s.decidedBy ? ('Approved by ' + s.decidedBy + (s.decidedAt ? ' · ' + s.decidedAt : '')) : 'Instant (published by Admin / HR)'); }
        var caps = [];
        if (s.maxClaims) { caps.push(s.maxClaims + ' claims/person'); }
        if (s.maxAmount) { caps.push('Rs ' + s.maxAmount + ' gross/person'); }
        commModal('<div class="card" style="max-width:560px;width:100%;padding:24px 26px;margin:auto">'
            + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><h3 style="margin:0;font-size:17px">' + s.title + '</h3><button class="btn btn-outline btn-sm" onclick="commModalClose()"><i class="fas fa-xmark"></i></button></div>'
            + '<div style="margin-bottom:10px">' + schemeStateChip(s.state) + '</div>'
            + row('Pays', schemeRateText(s) + (s.tdsRate !== null && s.tdsRate !== undefined ? ' · TDS ' + s.tdsRate + '%' : ''))
            + row('Purpose / Portfolio', (s.purpose || '') + (s.portfolio ? ' · ' + s.portfolio : ''))
            + row('Payout', s.payoutMethod === 'separate' ? 'Separate payout (ledger)' : 'With salary (payslip)')
            + row('Applies to', schemeAppliesText(s))
            + row('Window', (s.from || '—') + ' → ' + (s.till || 'open'))
            + row('Caps', caps.join(' · ') || 'No caps')
            + trail
            + row('Claims', s.claims + ' raised · ' + s.approved + ' approved · ' + (s.pendingClaims || 0) + ' pending · Rs ' + (s.approvedGross || 0) + ' approved gross')
            + (s.notes ? row('Note', s.notes) : '')
            + '<div style="display:flex;gap:10px;justify-content:flex-end;margin-top:16px">'
            + (s.canDecide ? '<button class="btn btn-primary" onclick="commModalClose();schemeDecide(' + s.id + ',&#39;approve&#39;)"><i class="fas fa-check"></i> Approve</button><button class="btn btn-outline" style="color:var(--red)" onclick="commModalClose();schemeDecide(' + s.id + ',&#39;reject&#39;)">Reject</button>' : '')
            + (s.canEdit ? '<button class="btn btn-outline" onclick="commModalClose();schemeFormOpen(' + s.id + ')"><i class="fas fa-pen"></i> Edit</button>' : '')
            + (s.canReopen ? '<button class="btn" style="background:#16a34a;color:#fff" onclick="commModalClose();schemeReopen(' + s.id + ')"><i class="fas fa-rotate-left"></i> Re-open</button>' : '')
            + '<button class="btn btn-outline" onclick="commModalClose()">Close</button>'
            + '</div></div>');
    };
    // rev 115d: approve/reject a pending scheme (creator's reporting manager or Admin).
    window.schemeDecide = function (id, action) {
        var remarks = '';
        if (action === 'reject') {
            remarks = window.prompt('Reason for rejecting (the creator sees this):', '');
            if (remarks === null) { return; }
        } else if (!window.confirm('Approve this scheme? It goes LIVE immediately and the team is announced.')) { return; }
        fetch(cfg.schemesBase + '/' + id + '/decide', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': cfg.csrf, 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify({ action: action, remarks: remarks }) })
            .then(function (r) { return r.json(); })
            .then(function (j) {
                if (j && j.ok) { if (typeof toast === 'function') { toast(j.message || 'Done'); } window.__SCHEMES = null; schemesLoad(); }
                else if (typeof toast === 'function') { toast((j && j.error) || 'Action failed'); }
            }).catch(function () {});
    };
    function schemeAppliesText(s) {
        if (s.appliesTo === 'all') { return 'All employees'; }
        if (s.appliesTo === 'team') { return 'Team: ' + (s.team || ''); }
        return (s.employeeIds || []).length + ' selected people';
    }
    function schemesScreen() {
        var d = window.__SCHEMES;
        if (!d) { setTimeout(function () { if (!window.__SCHEMES) { schemesLoad(); } }, 10); return pghead('Incentive Schemes', 'Loading…', '') + '<div class="card"><div style="padding:40px;text-align:center;color:var(--text3)">Loading schemes…</div></div>'; }
        var rows = d.rows || [];
        var btn = '<button class="btn btn-primary" onclick="schemeFormOpen()"><i class="fas fa-plus"></i> New Scheme</button>';
        var body = rows.map(function (s) {
            var caps = [];
            if (s.maxClaims) { caps.push(s.maxClaims + ' claims/person'); }
            if (s.maxAmount) { caps.push('Rs ' + s.maxAmount + '/person'); }
            return '<tr>'
                + '<td><a onclick="schemeView(' + s.id + ')" style="cursor:pointer"><b style="color:var(--accent);text-decoration:underline;text-decoration-style:dotted">' + s.title + '</b></a><div style="font-size:11.5px;color:var(--text3)">' + (s.purpose || '') + (s.portfolio ? ' · ' + s.portfolio : '') + (s.notes ? ' · ' + s.notes : '') + '</div></td>'
                + '<td>' + schemeRateText(s) + (s.tdsRate !== null && s.tdsRate !== undefined ? '<div style="font-size:11px;color:var(--text3)">TDS ' + s.tdsRate + '%</div>' : '') + '</td>'
                + '<td>' + schemeAppliesText(s) + '<div style="font-size:11px;color:var(--text3)">' + (s.payoutMethod === 'separate' ? 'Separate payout' : 'With salary') + '</div></td>'
                + '<td style="white-space:nowrap">' + (s.from || '—') + ' → ' + (s.till || 'open') + (caps.length ? '<div style="font-size:11px;color:var(--text3)">' + caps.join(' · ') + '</div>' : '') + '</td>'
                + '<td style="text-align:center"><b>' + s.claims + '</b> raised<div style="font-size:11px;color:var(--text3)">' + s.approved + ' approved · Rs ' + (s.approvedGross || 0) + '</div></td>'
                + '<td>' + schemeStateChip(s.state)
                + '<div style="font-size:11px;color:var(--text3);margin-top:3px">by ' + (s.createdBy || '') + '</div>'
                + (s.state === 'pending' && s.approver ? '<div style="font-size:11px;color:#92400e">awaiting ' + s.approver + '</div>' : '')
                + (s.state === 'rejected' ? '<div style="font-size:11px;color:#991b1b">' + (s.decidedBy ? 'by ' + s.decidedBy : '') + (s.rejectReason ? ' · ' + s.rejectReason : '') + '</div>' : '')
                + (s.approvalStatus === 'approved' && s.decidedBy ? '<div style="font-size:11px;color:#166534">approved by ' + s.decidedBy + '</div>' : '')
                + '</td>'
                + '<td style="white-space:nowrap">'
                + (s.canDecide ? '<button class="btn btn-primary btn-sm" onclick="schemeDecide(' + s.id + ',&#39;approve&#39;)"><i class="fas fa-check"></i> Approve</button> <button class="btn btn-outline btn-sm" onclick="schemeDecide(' + s.id + ',&#39;reject&#39;)" style="color:var(--red)">Reject</button> ' : '')
                + (s.canEdit ? '<button class="btn btn-outline btn-sm" onclick="schemeFormOpen(' + s.id + ')"><i class="fas fa-pen"></i> Edit</button> ' : '')
                + (s.canReopen ? '<button class="btn btn-sm" style="background:#16a34a;color:#fff" onclick="schemeReopen(' + s.id + ')"><i class="fas fa-rotate-left"></i> Re-open</button> ' : '')
                + (s.state === 'active' || s.state === 'upcoming' || s.state === 'pending' ? '<button class="btn btn-outline btn-sm" onclick="schemeWithdraw(' + s.id + ')" style="color:var(--red)">Withdraw</button>' : '')
                + '</td>'
                + '</tr>';
        }).join('');
        return pghead('Commission & Incentive Schemes', 'Publish offers your people claim against — month-wise, weekly or portfolio-wise, with expiry, caps and automatic announcements', btn)
            + '<div class="card" style="padding:0;overflow-x:auto"><table class="tbl" style="width:100%"><thead><tr><th>Scheme</th><th>Pays</th><th>Applies to</th><th>Window & caps</th><th style="text-align:center">Claims</th><th>Status</th><th></th></tr></thead><tbody>'
            + (body || '<tr><td colspan="7" style="text-align:center;color:var(--text3);padding:34px">No schemes yet. Click "New Scheme" — your people get notified the moment you publish, and the offer appears in their claim form automatically.</td></tr>')
            + '</tbody></table></div>';
    }
    window.schemeFormRate = function () {
        var t = (document.getElementById('sf_rate_type') || {}).value || 'open';
        var lab = document.getElementById('sf_rate_lab');
        var inp = document.getElementById('sf_rate_value');
        if (lab) { lab.textContent = t === 'percent' ? 'RATE — % OF COLLECTED AMOUNT' : (t === 'fixed' ? 'FIXED ₹ PER CLAIM' : 'RATE (NOT USED FOR OPEN ENTRIES)'); }
        if (inp) { inp.disabled = (t === 'open'); if (t === 'open') { inp.value = ''; } }
    };
    window.schemeFormApplies = function () {
        var t = (document.getElementById('sf_applies') || {}).value || 'all';
        var tr = document.getElementById('sf_team_row'); if (tr) { tr.style.display = t === 'team' ? 'block' : 'none'; }
        var er = document.getElementById('sf_emp_row'); if (er) { er.style.display = t === 'selected' ? 'block' : 'none'; }
        if (t === 'selected') { schemeEmpRender(); }   // rev 115b: build the cascading picker
    };
    // rev 115b (Ejaz): big teams — cascading picker Company → Branch → Team →
    // employees, with select-all-shown. Selections survive filter changes
    // (window.__SF_SEL keeps emp_code → name across re-renders).
    window.__SF_SEL = {};
    function sfCompanyName(e) {
        try {
            var cs = (DB.companies || []);
            var c = cs.find(function (x) { return String(x.id) === String(e.companyId || e.company_id || ''); });
            return c ? c.name : (e.company || '');
        } catch (er) { return e.company || ''; }
    }
    function sfFiltered() {
        var emps = ((typeof DB !== 'undefined' && DB.employees) || []);
        var co = (document.getElementById('sf_f_co') || {}).value || '';
        var br = (document.getElementById('sf_f_br') || {}).value || '';
        var tm = (document.getElementById('sf_f_tm') || {}).value || '';
        return emps.filter(function (e) {
            if (co && sfCompanyName(e) !== co) { return false; }
            if (br && (e.branch || '') !== br) { return false; }
            if (tm && (e.team || '') !== tm) { return false; }
            return true;
        });
    }
    window.schemeEmpFilter = function (level) {
        // Changing an upper filter resets the ones below it.
        if (level === 'co') { var b = document.getElementById('sf_f_br'); if (b) { b.value = ''; } var t = document.getElementById('sf_f_tm'); if (t) { t.value = ''; } }
        if (level === 'br') { var t2 = document.getElementById('sf_f_tm'); if (t2) { t2.value = ''; } }
        schemeEmpRender();
    };
    window.schemeEmpPick = function (cb) {
        if (cb.checked) { window.__SF_SEL[cb.value] = cb.getAttribute('data-name') || cb.value; }
        else { delete window.__SF_SEL[cb.value]; }
        schemeEmpCount();
    };
    window.schemeEmpAll = function (on) {
        sfFiltered().forEach(function (e) {
            if (on) { window.__SF_SEL[e.id] = e.name; } else { delete window.__SF_SEL[e.id]; }
        });
        schemeEmpRender();
    };
    function schemeEmpCount() {
        var n = Object.keys(window.__SF_SEL).length;
        var el = document.getElementById('sf_sel_count');
        if (el) { el.textContent = n ? (n + ' selected') : 'none selected'; }
    }
    window.schemeEmpRender = function () {
        var emps = ((typeof DB !== 'undefined' && DB.employees) || []);
        var co = (document.getElementById('sf_f_co') || {}).value || '';
        var br = (document.getElementById('sf_f_br') || {}).value || '';
        var tm = (document.getElementById('sf_f_tm') || {}).value || '';
        // Cascade option lists: branches within the company, teams within branch.
        var cos = {}; var brs = {}; var tms = {};
        emps.forEach(function (e) {
            var cn = sfCompanyName(e);
            if (cn) { cos[cn] = 1; }
            if ((!co || cn === co) && e.branch) { brs[e.branch] = 1; }
            if ((!co || cn === co) && (!br || (e.branch || '') === br) && e.team) { tms[e.team] = 1; }
        });
        var mkOpts = function (obj, cur, anyLabel) {
            return '<option value="">' + anyLabel + '</option>' + Object.keys(obj).sort().map(function (k) { return '<option' + (k === cur ? ' selected' : '') + '>' + k + '</option>'; }).join('');
        };
        var coEl = document.getElementById('sf_f_co'); if (coEl) { coEl.innerHTML = mkOpts(cos, co, 'All companies'); }
        var brEl = document.getElementById('sf_f_br'); if (brEl) { brEl.innerHTML = mkOpts(brs, br, 'All branches'); }
        var tmEl = document.getElementById('sf_f_tm'); if (tmEl) { tmEl.innerHTML = mkOpts(tms, tm, 'All teams'); }
        var list = sfFiltered();
        var box = document.getElementById('sf_emp_list');
        if (box) {
            box.innerHTML = list.map(function (e) {
                var on = window.__SF_SEL[e.id] ? ' checked' : '';
                return '<label style="display:flex;align-items:center;gap:7px;font-size:13px;padding:3px 0;cursor:pointer"><input type="checkbox" value="' + e.id + '" data-name="' + e.name + '" onchange="schemeEmpPick(this)"' + on + '>' + e.name + ' <span style="color:var(--text3);font-size:11px">' + e.id + (e.team ? ' · ' + e.team : '') + (e.branch ? ' · ' + e.branch : '') + '</span></label>';
            }).join('') || '<div style="color:var(--text3);font-size:13px;padding:8px 0">No employees match these filters</div>';
        }
        var shown = document.getElementById('sf_shown_count'); if (shown) { shown.textContent = list.length + ' shown'; }
        schemeEmpCount();
    };
    window.schemeFormOpen = function (editId) {
        window.__SF_SEL = {};
        window.__SF_EDIT_ID = editId || null;
        var ed = null;
        if (editId) {
            var rows0 = (window.__SCHEMES && window.__SCHEMES.rows) || [];
            ed = rows0.find(function (x) { return String(x.id) === String(editId); }) || null;
        }
        var inp = 'width:100%;padding:9px 11px;border:1.5px solid var(--border);border-radius:9px;font-size:14px;background:#f8fafc';
        var lbl = 'font-size:11px;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.4px;display:block;margin-bottom:4px';
        var emps = ((typeof DB !== 'undefined' && DB.employees) || []);
        var teams = {};
        emps.forEach(function (e) { if (e.team) { teams[e.team] = 1; } });
        var teamOpts = Object.keys(teams).sort().map(function (t) { return '<option>' + t + '</option>'; }).join('');
        var purposes = ['EMI Collection', 'Settlement / OTS', 'Recovery Incentive', 'Penalty Collection', 'Repo / Seizure', 'Target Bonus', 'Field Visit Allowance', 'Other'];
        commModal('<div class="card" style="max-width:760px;width:100%;padding:26px 28px;margin:auto">'
            + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><h3 style="margin:0;font-size:18px">' + (ed ? 'Edit Scheme' : 'New Commission / Incentive Scheme') + '</h3><button class="btn btn-outline btn-sm" onclick="commModalClose()"><i class="fas fa-xmark"></i></button></div>'
            + (ed && ed.claims > 0 ? '<div style="background:#fef3c7;border:1px solid #fde68a;border-radius:10px;padding:11px 15px;margin-bottom:13px;font-size:13px;color:#92400e"><i class="fas fa-triangle-exclamation"></i> <b>This scheme has ' + ed.claims + ' claim(s).</b> Changing the rate or TDS will RECALCULATE all unlocked claims — approved ones go back to Pending for re-approval. Locked (payslip-paid) claims never change.</div>' : '')
            + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:13px">'
            + '<div style="grid-column:1/3"><label style="' + lbl + '">Scheme title (your people see this)</label><input id="sf_title" style="' + inp + '" placeholder="e.g. June EMI Drive — HDFC portfolio"></div>'
            + '<div><label style="' + lbl + '">Purpose (prefills the claim)</label><select id="sf_purpose" style="' + inp + '">' + purposes.map(function (p) { return '<option>' + p + '</option>'; }).join('') + '</select></div>'
            + '<div><label style="' + lbl + '">Portfolio / Bank (optional)</label><input id="sf_portfolio" style="' + inp + '"></div>'
            + '<div><label style="' + lbl + '">How it pays</label><select id="sf_rate_type" style="' + inp + '" onchange="schemeFormRate()"><option value="percent">% of collected amount</option><option value="fixed">Fixed ₹ per claim</option><option value="open">Open — agent enters amount</option></select></div>'
            + '<div><label style="' + lbl + '" id="sf_rate_lab">RATE — % OF COLLECTED AMOUNT</label><input id="sf_rate_value" type="number" style="' + inp + '"></div>'
            + '<div><label style="' + lbl + '">TDS % (blank = claim default)</label><input id="sf_tds" type="number" style="' + inp + '"></div>'
            + '<div><label style="' + lbl + '">Payout method</label><select id="sf_payout" style="' + inp + '"><option value="with_salary">With salary (payslip)</option><option value="separate">Separate payout (ledger)</option></select></div>'
            + '<div><label style="' + lbl + '">Valid from</label><input id="sf_from" type="date" style="' + inp + '"></div>'
            + '<div><label style="' + lbl + '">Valid till (expiry)</label><input id="sf_till" type="date" style="' + inp + '"></div>'
            + '<div><label style="' + lbl + '">Who can claim</label><select id="sf_applies" style="' + inp + '" onchange="schemeFormApplies()"><option value="all">All employees</option><option value="team">One team</option><option value="selected">Selected people</option></select></div>'
            + '<div id="sf_team_row" style="display:none"><label style="' + lbl + '">Team</label><input id="sf_team" list="sf_teams" style="' + inp + '"><datalist id="sf_teams">' + teamOpts + '</datalist></div>'
            + '<div id="sf_emp_row" style="display:none;grid-column:1/3;border:1.5px solid var(--border);border-radius:9px;padding:12px 14px">'
            + '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:9px">'
            + '<select id="sf_f_co" style="' + inp + '" onchange="schemeEmpFilter(&#39;co&#39;)"></select>'
            + '<select id="sf_f_br" style="' + inp + '" onchange="schemeEmpFilter(&#39;br&#39;)"></select>'
            + '<select id="sf_f_tm" style="' + inp + '" onchange="schemeEmpFilter(&#39;tm&#39;)"></select>'
            + '</div>'
            + '<div style="display:flex;gap:14px;align-items:center;font-size:12px;margin-bottom:7px">'
            + '<a onclick="schemeEmpAll(1)" style="color:var(--accent);font-weight:700;cursor:pointer">Select all shown</a>'
            + '<a onclick="schemeEmpAll(0)" style="color:var(--text3);cursor:pointer">Clear shown</a>'
            + '<span id="sf_shown_count" style="color:var(--text3)"></span>'
            + '<span id="sf_sel_count" style="margin-left:auto;background:#fff7ed;color:#9a3412;font-weight:700;padding:2px 10px;border-radius:99px">none selected</span>'
            + '</div>'
            + '<div id="sf_emp_list" style="max-height:170px;overflow:auto"></div>'
            + '</div>'
            + '<div><label style="' + lbl + '">Max claims / person (blank = unlimited)</label><input id="sf_max_claims" type="number" style="' + inp + '"></div>'
            + '<div><label style="' + lbl + '">Max ₹ gross / person (blank = unlimited)</label><input id="sf_max_amount" type="number" style="' + inp + '"></div>'
            + '<div style="grid-column:1/3"><label style="' + lbl + '">Internal note (optional)</label><input id="sf_notes" style="' + inp + '"></div>'
            + '<div style="grid-column:1/3;border:1.5px solid var(--border);border-radius:11px;padding:11px 14px">'
            + '<label style="' + lbl + '">Announce to the selected people on</label>'
            + '<div style="display:flex;gap:22px;flex-wrap:wrap;font-size:13.5px;margin-top:4px">'
            + '<label style="display:flex;align-items:center;gap:7px;cursor:pointer"><input type="checkbox" id="sf_nf_email" checked style="width:16px;height:16px"><i class="fas fa-envelope" style="color:var(--text3)"></i> Email</label>'
            + '<label style="display:flex;align-items:center;gap:7px;cursor:pointer"><input type="checkbox" id="sf_nf_wa" checked style="width:16px;height:16px"><i class="fab fa-whatsapp" style="color:#16a34a"></i> WhatsApp</label>'
            + '<label style="display:flex;align-items:center;gap:7px;cursor:pointer"><input type="checkbox" id="sf_nf_notice" checked style="width:16px;height:16px"><i class="fas fa-thumbtack" style="color:var(--accent)"></i> Notice board</label>'
            + '</div>'
            + '<div style="font-size:11.5px;color:var(--text3);margin-top:5px">Untick all = silent publish (the scheme still appears in claim forms and on Live Salary).</div>'
            + '</div>'
            + '</div>'
            + '<div style="display:flex;gap:10px;justify-content:flex-end;margin-top:18px"><button class="btn btn-outline" onclick="commModalClose()">Cancel</button><button class="btn btn-primary" id="sf_save" onclick="schemeFormSave()"><i class="fas fa-bullhorn"></i> ' + (ed ? 'Save changes' : 'Publish scheme') + '</button></div>'
            + '</div>');
        // rev 115g: EDIT — prefill after the modal exists (no attribute-escaping risk).
        if (ed) {
            var sv = function (id2, v2) { var el2 = document.getElementById(id2); if (el2 && v2 !== null && v2 !== undefined) { el2.value = v2; } };
            sv('sf_title', ed.title);
            var pe = document.getElementById('sf_purpose');
            if (pe && ed.purpose) {
                var hasP = false;
                for (var pi = 0; pi < pe.options.length; pi++) { if (pe.options[pi].text === ed.purpose) { hasP = true; } }
                if (!hasP) { var po = document.createElement('option'); po.text = ed.purpose; pe.add(po); }
                pe.value = ed.purpose;
            }
            sv('sf_portfolio', ed.portfolio);
            sv('sf_rate_type', ed.rateType); schemeFormRate();
            sv('sf_rate_value', ed.rateValue);
            sv('sf_tds', ed.tdsRate);
            sv('sf_payout', ed.payoutMethod);
            sv('sf_from', ed.from);
            sv('sf_till', ed.till);
            sv('sf_applies', ed.appliesTo);
            sv('sf_team', ed.team);
            sv('sf_max_claims', ed.maxClaims);
            sv('sf_max_amount', ed.maxAmount);
            sv('sf_notes', ed.notes);
            (ed.employeeCodes || []).forEach(function (cd) {
                var emp0 = ((typeof DB !== 'undefined' && DB.employees) || []).find(function (e0) { return String(e0.id) === String(cd); });
                window.__SF_SEL[cd] = emp0 ? emp0.name : cd;
            });
            // Edit: restore the creator's channel choices (default: none re-announced).
            var chs = ed.notifyChannels || [];
            var setCh = function (id3, key) { var el3 = document.getElementById(id3); if (el3) { el3.checked = chs.indexOf(key) >= 0; } };
            setCh('sf_nf_email', 'email'); setCh('sf_nf_wa', 'wa'); setCh('sf_nf_notice', 'notice');
            schemeFormApplies();
        }
    };
    window.schemeFormSave = function () {
        var val = function (id) { var el = document.getElementById(id); return el ? el.value : ''; };
        if (!val('sf_title').trim()) { if (typeof toast === 'function') { toast('Give the scheme a title'); } return; }
        // rev 115b: selections persist across filter changes in __SF_SEL.
        var codes = Object.keys(window.__SF_SEL || {});
        var body = {
            title: val('sf_title').trim(), purpose: val('sf_purpose'), portfolio: val('sf_portfolio'),
            rate_type: val('sf_rate_type'), rate_value: val('sf_rate_value') || null,
            tds_rate: val('sf_tds') || null, payout_method: val('sf_payout'),
            valid_from: val('sf_from') || null, valid_till: val('sf_till') || null,
            applies_to: val('sf_applies'), team: val('sf_team') || null,
            employee_codes: codes,
            max_claims: val('sf_max_claims') || null, max_amount: val('sf_max_amount') || null,
            notes: val('sf_notes') || null,
            notify_email: (document.getElementById('sf_nf_email') || {}).checked ? 1 : 0,
            notify_wa: (document.getElementById('sf_nf_wa') || {}).checked ? 1 : 0,
            notify_notice: (document.getElementById('sf_nf_notice') || {}).checked ? 1 : 0,
            id: window.__SF_EDIT_ID || null
        };
        var b = document.getElementById('sf_save'); if (b) { b.disabled = true; }
        fetch(cfg.schemesBase, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': cfg.csrf, 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify(body) })
            .then(function (r) { return r.json(); })
            .then(function (j) {
                if (b) { b.disabled = false; }
                if (j && j.ok) { if (typeof toast === 'function') { toast(j.message || 'Scheme published'); } commModalClose(); window.__SCHEMES = null; schemesLoad(); }
                else if (typeof toast === 'function') { toast((j && j.error) || 'Could not save'); }
            })
            .catch(function () { if (b) { b.disabled = false; } if (typeof toast === 'function') { toast('Could not save'); } });
    };
    // rev 116f (Ejaz): withdraw = a REAL confirmation dialog — shows how many
    // claims exist, and the choice: keep the already-claimed in approval, or
    // full withdraw (reject pending too). Approved claims always stay.
    window.schemeWithdraw = function (id) {
        var rows = (window.__SCHEMES && window.__SCHEMES.rows) || [];
        var s = rows.find(function (x) { return String(x.id) === String(id); });
        if (!s) { return; }
        var pend = s.pendingClaims || 0;
        var summary = s.claims > 0
            ? '<div style="background:#fef3c7;border:1px solid #fde68a;border-radius:10px;padding:12px 16px;margin:12px 0;font-size:13.5px;color:#92400e">'
                + '<b><i class="fas fa-triangle-exclamation"></i> This scheme already has ' + s.claims + ' claim(s):</b><br>'
                + '&bull; ' + s.approved + ' approved (Rs ' + (s.approvedGross || 0) + ' gross) &mdash; these ALWAYS stay; corrections go through Clawbacks.<br>'
                + '&bull; ' + pend + ' still awaiting approval.'
                + '</div>'
            : '<div style="font-size:13.5px;color:var(--text2);margin:12px 0">No claims have been raised against it yet.</div>';
        var btns = '';
        if (pend > 0) {
            btns = '<button class="btn btn-outline" style="color:#92400e;border-color:#fde68a" onclick="schemeWithdrawGo(' + s.id + ',0)"><i class="fas fa-box-archive"></i> Withdraw — KEEP the ' + pend + ' pending claim(s) in approval</button>'
                + '<button class="btn" style="background:var(--red);color:#fff" onclick="schemeWithdrawGo(' + s.id + ',1)"><i class="fas fa-ban"></i> Full withdraw — also REJECT the ' + pend + ' pending claim(s)</button>';
        } else {
            btns = '<button class="btn" style="background:var(--red);color:#fff" onclick="schemeWithdrawGo(' + s.id + ',0)"><i class="fas fa-ban"></i> Yes, withdraw this scheme</button>';
        }
        commModal('<div class="card" style="max-width:520px;width:100%;padding:24px 26px;margin:auto">'
            + '<h3 style="margin:0 0 4px;font-size:17px">Withdraw "' + s.title + '"?</h3>'
            + '<div style="font-size:12.5px;color:var(--text3)">It disappears from claim forms and Live Salary ribbons immediately.</div>'
            + summary
            + '<div style="display:flex;flex-direction:column;gap:10px;margin-top:6px">' + btns
            + '<button class="btn btn-outline" onclick="commModalClose()">Cancel — keep the scheme running</button></div>'
            + '</div>');
    };
    // rev 117: undo a mistaken withdrawal — restores withdrawal-rejected claims.
    window.schemeReopen = function (id) {
        if (!window.confirm('Re-open this scheme? It returns to claim forms, and claims that were rejected by the withdrawal are RESTORED to Pending.')) { return; }
        fetch(cfg.schemesBase + '/' + id + '/reopen', { method: 'POST', credentials: 'same-origin', headers: { 'X-CSRF-TOKEN': cfg.csrf, 'X-Requested-With': 'XMLHttpRequest' } })
            .then(function (r) { return r.json(); })
            .then(function (j) {
                if (j && j.ok) { if (typeof toast === 'function') { toast(j.message || 'Scheme re-opened'); } window.__SCHEMES = null; schemesLoad(); }
                else if (typeof toast === 'function') { toast((j && j.error) || 'Could not re-open'); }
            }).catch(function () {});
    };
    window.schemeWithdrawGo = function (id, rejectPending) {
        commModalClose();
        fetch(cfg.schemesBase + '/' + id + '/withdraw', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': cfg.csrf, 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify({ reject_pending: rejectPending }) })
            .then(function (r) { return r.json(); })
            .then(function (j) {
                if (j && j.ok) { if (typeof toast === 'function') { toast('Scheme withdrawn'); } window.__SCHEMES = null; schemesLoad(); }
                else if (typeof toast === 'function') { toast((j && j.error) || 'Could not withdraw'); }
            }).catch(function () {});
    };
    // ---- rev 115: SCHEME PICKER on the commission claim form -----------------
    // Active schemes for the signed-in user load once per modal open; picking
    // one AUTO-FILLS purpose/portfolio/TDS/payout and computes the money:
    // percent → collected-base input appears (gross = base × rate), fixed →
    // gross fills itself, open → prefill only. Server re-validates everything.
    window.__SCHEMES_ME = null;
    function schemeRateText(s) {
        if (s.rateType === 'percent') { return s.rateValue + '% of collected amount'; }
        if (s.rateType === 'fixed') { return 'Rs ' + s.rateValue + ' per claim'; }
        return 'amount as per entry';
    }
    window.schemeInjectUI = function () {
        var rows = (window.__SCHEMES_ME && window.__SCHEMES_ME.rows) || [];
        if (!rows.length) { return; }
        var empSel = document.getElementById('rq_emp'); if (!empSel) { return; }
        if (document.getElementById('sp-scheme-cell')) { return; }
        var grid = empSel.parentNode.parentNode;
        var cell = document.createElement('div');
        cell.id = 'sp-scheme-cell';
        cell.style.cssText = 'grid-column:1/3;background:#fff7ed;border:1.5px solid #fed7aa;border-radius:11px;padding:12px 14px';
        var opts = rows.map(function (s) { return '<option value="' + s.id + '">' + s.title + ' — ' + schemeRateText(s) + (s.till ? ' (till ' + s.till + ')' : '') + '</option>'; }).join('');
        cell.innerHTML = '<label style="font-size:11px;font-weight:700;color:#9a3412;text-transform:uppercase;letter-spacing:.4px;display:block;margin-bottom:4px"><i class="fas fa-bullseye"></i> Claim against a scheme (optional)</label>'
            + '<select id="sp-scheme-pick" onchange="schemePick()" style="width:100%;padding:9px 11px;border:1.5px solid #fed7aa;border-radius:9px;font-size:14px;background:#fff"><option value="">No scheme — free entry</option>' + opts + '</select>'
            + '<div id="sp-scheme-info" style="display:none;font-size:12px;color:#9a3412;margin-top:8px"></div>';
        grid.insertBefore(cell, grid.firstChild);
    };
    window.schemePick = function () {
        var rows = (window.__SCHEMES_ME && window.__SCHEMES_ME.rows) || [];
        var sel = document.getElementById('sp-scheme-pick');
        var hid = document.getElementById('rqf_scheme_id');
        var info = document.getElementById('sp-scheme-info');
        var gEl = document.getElementById('rqf_gross_amount');
        var id = sel ? sel.value : '';
        var s = rows.find(function (x) { return String(x.id) === String(id); });
        if (hid) { hid.value = s ? s.id : ''; }
        if (!s) {
            if (info) { info.style.display = 'none'; }
            if (gEl) { gEl.readOnly = false; gEl.style.background = '#f8fafc'; }
            return;
        }
        // Autofill the form from the scheme.
        var pEl = document.getElementById('rqf_purpose');
        if (pEl && s.purpose) {
            var has = false;
            for (var i = 0; i < pEl.options.length; i++) { if (pEl.options[i].value === s.purpose || pEl.options[i].text === s.purpose) { has = true; pEl.selectedIndex = i; } }
            if (!has) { var op = document.createElement('option'); op.text = s.purpose; pEl.add(op); pEl.value = s.purpose; }
        }
        var pf = document.getElementById('rqf_portfolio'); if (pf && s.portfolio) { pf.value = s.portfolio; }
        var td = document.getElementById('rqf_tds_rate'); if (td && s.tdsRate !== null && s.tdsRate !== undefined) { td.value = s.tdsRate; }
        var pm = document.getElementById('rqf_payout_method'); if (pm) { pm.selectedIndex = (s.payoutMethod === 'separate') ? 1 : 0; }
        if (info) {
            var bits = ['Pays ' + schemeRateText(s)];
            if (s.claimsLeft !== null && s.claimsLeft !== undefined) { bits.push(s.claimsLeft + ' claim(s) left for you'); }
            if (s.amountLeft !== null && s.amountLeft !== undefined) { bits.push('Rs ' + s.amountLeft + ' cap remaining'); }
            if (s.till) { bits.push('valid till ' + s.till); }
            info.innerHTML = '<i class="fas fa-circle-info"></i> ' + bits.join(' · ');
            info.style.display = 'block';
        }
        // rev 116c: the VISIBLE "Amount Collected from Customer" field drives the
        // percent computation — gross goes read-only under a % or fixed scheme.
        if (s.rateType === 'percent') {
            if (gEl) { gEl.readOnly = true; gEl.style.background = '#eef2f7'; }
            schemeBaseCalc();
        } else if (s.rateType === 'fixed') {
            if (gEl) { gEl.value = s.rateValue; gEl.readOnly = true; gEl.style.background = '#eef2f7'; }
            rqCommCalc();
        } else {
            if (gEl) { gEl.readOnly = false; gEl.style.background = '#f8fafc'; }
        }
    };
    window.schemeBaseCalc = function () {
        var rows = (window.__SCHEMES_ME && window.__SCHEMES_ME.rows) || [];
        var sel = document.getElementById('sp-scheme-pick');
        var s = rows.find(function (x) { return String(x.id) === String(sel ? sel.value : ''); });
        if (!s || s.rateType !== 'percent') { return; }
        var base = Number((document.getElementById('rqf_base_amount') || {}).value || 0);
        var gEl = document.getElementById('rqf_gross_amount');
        if (gEl) { gEl.value = base > 0 ? Math.round(base * s.rateValue) / 100 : ''; }
        rqCommCalc();
    };
    // rev 115h: the picker follows the SELECTED employee (an Admin entering for
    // Asha must see ASHA's schemes — the signed-in admin has no employee record).
    window.schemeFetchFor = function (empName) {
        var url = cfg.schemesBase + '/for-me' + (empName ? ('?employee=' + encodeURIComponent(empName)) : '');
        fetch(url, { headers: { 'X-Requested-With': 'XMLHttpRequest' }, credentials: 'same-origin' })
            .then(function (r) { return r.json(); })
            .then(function (j) {
                window.__SCHEMES_ME = j;
                // Employee changed → drop any previous scheme choice + unlock gross.
                var old = document.getElementById('sp-scheme-cell');
                if (old && old.parentNode) { old.parentNode.removeChild(old); }
                var hid = document.getElementById('rqf_scheme_id'); if (hid) { hid.value = ''; }
                var bHid = document.getElementById('rqf_base_amount'); if (bHid) { bHid.value = ''; }
                var gEl = document.getElementById('rqf_gross_amount'); if (gEl) { gEl.readOnly = false; gEl.style.background = '#f8fafc'; }
                schemeInjectUI();
            })
            .catch(function () {});
    };
    // rev 116: PAYMENT PROOF upload box (screenshot / deposit slip) — required
    // server-side whenever the money did not come as cash to the office.
    window.commProofInjectUI = function () {
        var empSel = document.getElementById('rq_emp'); if (!empSel) { return; }
        if (document.getElementById('sp-proof-cell')) { return; }
        var grid = empSel.parentNode.parentNode;
        var cell = document.createElement('div');
        cell.id = 'sp-proof-cell';
        cell.style.cssText = 'grid-column:1/3;border:1.5px dashed var(--border);border-radius:11px;padding:11px 14px';
        cell.innerHTML = '<label style="font-size:11px;font-weight:700;color:var(--text2);text-transform:uppercase;letter-spacing:.4px;display:block;margin-bottom:5px"><i class="fas fa-receipt"></i> Payment proof — screenshot / deposit slip (image or PDF)</label>'
            + '<input type="file" id="sp-proof-file" accept="image/*,.pdf" onchange="commProofUpload()" style="font-size:13px">'
            + '<div id="sp-proof-status" style="font-size:12px;color:var(--text3);margin-top:5px">Optional — Accounts verifies against the bank&#39;s payments-received list; attaching a proof speeds your confirmation up.</div>';
        grid.appendChild(cell);
    };
    window.commProofUpload = function () {
        var f = document.getElementById('sp-proof-file');
        var st = document.getElementById('sp-proof-status');
        if (!f || !f.files || !f.files[0]) { return; }
        if (st) { st.innerHTML = 'Uploading…'; }
        var fd = new FormData();
        fd.append('file', f.files[0]);
        fetch(cfg.requestsBase + '/commissions/proof-upload', { method: 'POST', credentials: 'same-origin', headers: { 'X-CSRF-TOKEN': cfg.csrf, 'X-Requested-With': 'XMLHttpRequest' }, body: fd })
            .then(function (r) { return r.json(); })
            .then(function (j) {
                if (j && j.ok) {
                    var hid = document.getElementById('rqf_proof_path'); if (hid) { hid.value = j.path; }
                    if (st) { st.innerHTML = '<span style="color:#166534;font-weight:700"><i class="fas fa-circle-check"></i> Proof attached</span>'; }
                } else {
                    if (st) { st.innerHTML = '<span style="color:#b91c1c">' + ((j && j.error) || 'Upload failed') + '</span>'; }
                }
            })
            .catch(function () { if (st) { st.innerHTML = '<span style="color:#b91c1c">Upload failed — retry</span>'; } });
    };
    // rev 116d: show/hide the collection-evidence fields by claim type.
    window.commClaimTypeToggle = function () {
        var sel = document.getElementById('rqf_claim_type');
        var simple = !!(sel && sel.value.toLowerCase().indexOf('simple') >= 0);
        ['customer_name', 'account_ref', 'collection_type', 'collected_at', 'collection_location', 'collection_mode', 'base_amount'].forEach(function (k) {
            var el = document.getElementById('rqf_' + k);
            if (el && el.parentNode) { el.parentNode.style.display = simple ? 'none' : ''; }
        });
        var pc = document.getElementById('sp-proof-cell'); if (pc) { pc.style.display = simple ? 'none' : ''; }
    };
    // rev 116: Accounts confirmation — the stage BEFORE manager approval.
    window.commAccounts = function (id, action) {
        var note = '';
        if (action === 'flag') {
            note = window.prompt('What is wrong with this collection? (the agent and manager see this)', '');
            if (note === null) { return; }
        } else if (!window.confirm('Confirm that this money has actually been received by the company?')) { return; }
        fetch(cfg.requestsBase + '/commissions/' + id + '/accounts', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': cfg.csrf, 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify({ action: action, note: note }) })
            .then(function (r) { return r.json(); })
            .then(function (j) {
                if (j && j.ok) { if (typeof toast === 'function') { toast(j.message || 'Done'); } requestLoad('commissions'); }
                else if (typeof toast === 'function') { toast((j && j.error) || 'Action failed'); }
            }).catch(function () {});
    };
    (function () {
        var prev = window.reqApplyOpen;
        window.reqApplyOpen = function (navId) {
            prev(navId);
            if (navId !== 'commissions') { return; }
            var empSel = document.getElementById('rq_emp');
            if (empSel && !empSel.__schemeWired) {
                empSel.__schemeWired = true;
                empSel.addEventListener('change', function () { schemeFetchFor(empSel.value || ''); });
            }
            schemeFetchFor(empSel ? (empSel.value || '') : '');
            commProofInjectUI();
        };
    })();
    window.reqApplySave = function (navId) {
        var rc = RQ_MAP[navId]; if (!rc) { return; }
        var emp = (document.getElementById('rq_emp') || {}).value || '';
        if (!emp) { if (typeof toast === 'function') { toast('Select an employee'); } return; }
        if (navId === 'commissions') {
            var gv = Number((document.getElementById('rqf_gross_amount') || {}).value || 0);
            if (!(gv > 0)) { if (typeof toast === 'function') { toast('Enter the gross amount'); } return; }
            rqCommCalc();
        }
        var fields = {};
        rc.fields.forEach(function (fl) { var el = document.getElementById('rqf_' + fl.k); if (el && el.value !== '') { fields[fl.k] = el.value; } });
        var payload = { employee: emp, fields: fields };
        if (rc.amount) { var av = (document.getElementById('rq_amount') || {}).value; if (av !== '') { payload.amount = Number(av); } }
        fetch(cfg.requestsBase + '/' + rc.m, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': cfg.csrf, 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify(payload) })
            .then(function (r) { return r.json(); }).then(function (d) {
                if (d && d.ok) { if (typeof toast === 'function') { toast('Submitted · approver: ' + (d.approver || 'manager')); } reqApplyClose(); requestLoad(navId); window.__APPROVALS = null; }
                else if (typeof toast === 'function') { toast((d && d.error) || 'Could not submit'); }
            }).catch(function () { if (typeof toast === 'function') { toast('Could not submit'); } });
    };
    window.reqDecide = function (module, id, action) {
        var remarks = window.prompt((action === 'approve' ? 'Approve' : 'Reject') + ' this request — remarks (optional):', '');
        if (remarks === null) { return; }
        fetch(cfg.requestsBase + '/' + module + '/' + id + '/decide', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': cfg.csrf, 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify({ action: action, remarks: remarks }) })
            .then(function (r) { return r.json().then(function (j) { return { ok: r.ok, j: j }; }); })
            .then(function (res) {
                if (res.ok && res.j && res.j.ok) {
                    if (typeof toast === 'function') { toast('Request ' + res.j.status + (res.j.warning ? ' - ' + res.j.warning : '')); }
                    window.__APPROVALS = null;
                    // Refresh whichever request screen is loaded.
                    Object.keys(RQ_MAP).forEach(function (k) { if (RQ_MAP[k].m === module && window.__REQ[k]) { requestLoad(k); } });
                    if (typeof render === 'function') { render(); }
                } else if (typeof toast === 'function') { toast((res.j && res.j.error) || 'Action failed'); }
            }).catch(function () { if (typeof toast === 'function') { toast('Action failed'); } });
    };
    // rev181 — BOUNCE a commission: cheque returned / settlement cancelled.
    // Already-paid entries get an auto-created APPROVED clawback (recovered on
    // the next payslip); unpaid entries are simply rejected. Reason mandatory.
    window.commBounce = function (id) {
        var reason = window.prompt('Mark BOUNCED - what happened? (cheque returned, settlement cancelled, payment reversed...)', '');
        if (reason === null) { return; }
        if (!reason.replace(/ /g, '')) { if (typeof toast === 'function') { toast('A reason is required for a bounce'); } return; }
        if (!window.confirm('Confirm the bounce? If money was already paid on this entry, an APPROVED clawback is created automatically and recovers from the next payslip.')) { return; }
        fetch(cfg.requestsBase + '/commissions/' + id + '/bounce', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': cfg.csrf, 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify({ reason: reason }) })
            .then(function (r) { return r.json(); })
            .then(function (j) {
                if (j && j.ok) {
                    if (typeof toast === 'function') { toast(j.message || 'Bounce recorded'); }
                    Object.keys(RQ_MAP).forEach(function (k) { if ((RQ_MAP[k].m === 'commissions' || RQ_MAP[k].m === 'clawbacks') && window.__REQ[k]) { requestLoad(k); } });
                    if (typeof render === 'function') { render(); }
                } else if (typeof toast === 'function') { toast((j && j.error) || 'Bounce failed'); }
            }).catch(function () { if (typeof toast === 'function') { toast('Bounce failed'); } });
    };
    // Inbox dispatcher: leave items use leaveDecide, all others use reqDecide.
    window.inboxDecide = function (module, id, action) {
        if (module === 'leave') { return leaveDecide(id, action); }
        return reqDecide(module, id, action);
    };
    // ---- rev 83 (Ejaz): commission BULK UPLOAD (Excel/CSV) -------------------
    // The file they already keep in Excel goes straight in: each row becomes a
    // PENDING entry with the employee's own hierarchy approver (his choice).
    window.commBulkTemplate = function () {
        var nl = String.fromCharCode(10);
        var lines = [
            'Emp Code or Name,Month,Claim Kind (collection/simple),Purpose,Customer,Account No / ID,Collection Type,Collected On,Location,Mode (office/deposited/direct/online),Collected Amount,Portfolio / Bank,Gross Commission,TDS %,Payout Date,Payout Method (salary/separate),Description',
            'EMP101,May 2026,collection,EMI Collection,Ramesh Kumar,LN-448812,EMI,2026-05-28 16:30,Nellore,deposited,42000,HDFC Two-Wheeler,840,5,2026-07-10,salary,22nd EMI collected',
            'EMP102,May 2026,collection,Settlement / OTS,Sunita Devi,CC-90211,Settlement,2026-05-30 11:00,Guntur,direct,125000,ICICI Personal Loan,12500,,2026-07-10,separate,OTS closure incentive',
            'EMP103,May 2026,simple,Target Bonus,,,,,,,,,5000,,2026-07-10,salary,Q1 bucket target achieved'
        ];
        var blob = new Blob([lines.join(nl)], { type: 'text/csv' });
        var a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'smartprs-commissions-template.csv'; a.click();
    };
    window.commBulkClose = function () { var m = document.getElementById('comm-bulk-modal'); if (m) { m.style.display = 'none'; } };
    window.commBulkOpen = function () {
        var m = document.getElementById('comm-bulk-modal') || (function () { var x = document.createElement('div'); x.id = 'comm-bulk-modal'; document.body.appendChild(x); return x; })();
        m.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:1000;display:flex;align-items:flex-start;justify-content:center;padding:40px 16px;overflow:auto';
        m.innerHTML = '<div class="card" style="max-width:560px;width:100%;padding:0">'
            + '<div style="display:flex;align-items:center;justify-content:space-between;padding:18px 22px;border-bottom:1px solid var(--border)"><h3 style="margin:0;font-size:18px">Upload Commission Entries</h3><button class="btn btn-outline btn-sm" onclick="commBulkClose()"><i class="fas fa-xmark"></i></button></div>'
            + '<div style="padding:22px">'
            + '<div style="font-size:13px;color:var(--text2);line-height:1.6;margin-bottom:12px">Excel or CSV with columns: <b>Emp Code or Name, Month, Claim Kind (collection/simple), Purpose, Customer, Account No / ID, Collection Type, Collected On, Location, Mode, Collected Amount, Portfolio / Bank, Gross Commission, TDS %, Payout Date, Payout Method, Description</b>. <b>collection</b> rows = customer money collected (Accounts must confirm before approval); <b>simple</b> rows = target / bonus / incentive (leave customer columns blank — straight to manager approval). TDS % blank = 5% auto. Mode: office / deposited / direct / online. Employees uploading their own claims: every row is created for YOU automatically. Up to 1,000 rows.</div>'
            + '<a onclick="commBulkTemplate()" style="cursor:pointer;color:#4f46e5;font-size:13px;font-weight:600"><i class="fas fa-download"></i> Download template (CSV)</a>'
            + '<div style="margin:14px 0"><input type="file" id="commBulkFile" accept=".xlsx,.xls,.csv,text/csv" style="width:100%;padding:9px 11px;border:1.5px solid var(--border);border-radius:9px;font-size:13px;background:#f8fafc"></div>'
            + '<div id="commBulkMsg" style="font-size:12.5px;line-height:1.6;color:var(--text2)"></div>'
            + '</div>'
            + '<div style="display:flex;gap:10px;justify-content:flex-end;padding:0 22px 20px"><button class="btn btn-outline" onclick="commBulkClose()">Close</button><button class="btn btn-primary" id="commBulkBtn" onclick="commBulkGo()"><i class="fas fa-file-import"></i> Upload</button></div>'
            + '</div>';
        m.style.display = 'flex';
        m.onclick = function (e) { if (e.target === m) { commBulkClose(); } };
    };
    window.commBulkGo = function () {
        var fEl = document.getElementById('commBulkFile');
        var msg = document.getElementById('commBulkMsg');
        if (!fEl || !fEl.files || !fEl.files.length) { if (typeof toast === 'function') { toast('Choose a file first'); } return; }
        var setMsg = function (h) { if (msg) { msg.innerHTML = h; } };
        setMsg('Reading file…');
        abEnsureXLSX(function () {
            var rd = new FileReader();
            rd.onload = function (ev) {
                try {
                    var wb = XLSX.read(new Uint8Array(ev.target.result), { type: 'array' });
                    var ws = wb.Sheets[wb.SheetNames[0]];
                    var raw = XLSX.utils.sheet_to_json(ws, { defval: '', raw: false });
                    var out = [];
                    raw.forEach(function (r) {
                        var o = {};
                        Object.keys(r).forEach(function (h) {
                            var k = String(h).toLowerCase();
                            var val = String(r[h]).trim();
                            if (val === '') { return; }
                            // rev 116c: collection evidence columns — matched BEFORE
                            // the employee rule ("Customer" contains no emp/code, but
                            // order still matters for name/amount overlaps).
                            if (k.indexOf('claim') >= 0) { o.claim_type = val; }
                            else if (k.indexOf('account') >= 0 || k.indexOf('cc no') >= 0) { o.account_ref = val; }
                            else if (k.indexOf('customer') >= 0 && k.indexOf('amount') < 0) { o.customer_name = val; }
                            else if (k.indexOf('collected on') >= 0 || k.indexOf('collected at') >= 0) { o.collected_at = val; }
                            else if (k.indexOf('collect') >= 0 && k.indexOf('amount') >= 0) { var ca = Number(val.replace(/[^0-9.]/g, '')); if (ca > 0) { o.base_amount = ca; } }
                            else if (k.indexOf('collection type') >= 0 || k.indexOf('what was') >= 0) { o.collection_type = val; }
                            else if (k.indexOf('location') >= 0) { o.collection_location = val; }
                            else if (k.indexOf('mode') >= 0 && k.indexOf('method') < 0) { o.collection_mode = val; }
                            else if (!o.employee && (k.indexOf('emp') >= 0 || k.indexOf('name') >= 0 || k.indexOf('code') >= 0)) { o.employee = val; }
                            else if (k.indexOf('method') >= 0) { o.payout_method = val; }
                            else if (k.indexOf('payout') >= 0) { o.payout_date = val; }
                            else if (k.indexOf('month') >= 0) { o.month = val; }
                            else if (k.indexOf('purpose') >= 0 || k.indexOf('reason') >= 0) { o.purpose = val; }
                            else if (k.indexOf('portfolio') >= 0 || k.indexOf('bank') >= 0) { o.portfolio = val; }
                            else if (k.indexOf('gross') >= 0 || k.indexOf('amount') >= 0) { var n = Number(val.replace(/[^0-9.]/g, '')); if (n > 0 && !o.gross) { o.gross = n; } }
                            else if (k.indexOf('tds') >= 0) { var t = Number(val.replace(/[^0-9.]/g, '')); if (!isNaN(t)) { o.tds_rate = t; } }
                            else if (k.indexOf('desc') >= 0 || k.indexOf('note') >= 0 || k.indexOf('remark') >= 0) { o.description = val; }
                        });
                        // rev 116d: employee may be blank — agents' own uploads are
                        // forced to themselves server-side.
                        if (o.gross > 0) { out.push(o); }
                    });
                    if (!out.length) { setMsg('<span style="color:var(--red)">No usable rows found. Each row needs at least an employee and a gross amount &gt; 0. Download the template to see the expected columns.</span>'); return; }
                    if (out.length > 1000) { out = out.slice(0, 1000); }
                    setMsg('Uploading ' + out.length + ' row(s)…');
                    fetch(cfg.requestsBase + '/commissions/bulk', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': cfg.csrf, 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify({ rows: out }) })
                        .then(function (r) { return r.json(); })
                        .then(function (j) {
                            if (!j || !j.ok) { setMsg('<span style="color:var(--red)">' + ((j && j.error) || 'Upload failed') + '</span>'); return; }
                            var h = '<span style="color:#16a34a;font-weight:700">' + (j.message || 'Done') + '</span>';
                            if (j.errors && j.errors.length) { h += '<div style="color:var(--red);margin-top:8px">' + j.errors.join('<br>') + '</div>'; }
                            setMsg(h);
                            if (typeof toast === 'function') { toast((j.created || 0) + ' commission entr' + (j.created === 1 ? 'y' : 'ies') + ' created'); }
                            requestLoad('commissions'); window.__APPROVALS = null;
                        }).catch(function () { setMsg('<span style="color:var(--red)">Upload failed — network error.</span>'); });
                } catch (e2) { setMsg('<span style="color:var(--red)">Could not read the file. Make sure it is a valid .xlsx or .csv.</span>'); }
            };
            rd.readAsArrayBuffer(fEl.files[0]);
        });
    };
    // ---- rev 84 (Ejaz, USP): commission lifecycle — history / edit / reopen /
    // lock + self-claim. Entries are NEVER deleted; everything is logged.
    function commModal(html) {
        var m = document.getElementById('comm-modal') || (function () { var x = document.createElement('div'); x.id = 'comm-modal'; document.body.appendChild(x); return x; })();
        m.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:9000;display:flex;align-items:flex-start;justify-content:center;padding:40px 16px;overflow:auto';
        m.innerHTML = html;
        m.style.display = 'flex';
        m.onclick = function (e) { if (e.target === m) { commModalClose(); } };
    }
    window.commModalClose = function () { var m = document.getElementById('comm-modal'); if (m) { m.style.display = 'none'; } };
    window.commHist = function (id) {
        commModal('<div class="card" style="max-width:620px;width:100%;padding:0"><div style="display:flex;align-items:center;justify-content:space-between;padding:18px 22px;border-bottom:1px solid var(--border)"><h3 style="margin:0;font-size:17px"><i class="fas fa-clock-rotate-left"></i> Entry History #' + id + '</h3><button class="btn btn-outline btn-sm" onclick="commModalClose()"><i class="fas fa-xmark"></i></button></div><div id="commHistBody" style="padding:20px 22px;color:var(--text3);font-size:13px">Loading…</div></div>');
        fetch(cfg.requestsBase + '/commissions/' + id + '/history', { headers: { 'X-Requested-With': 'XMLHttpRequest' }, credentials: 'same-origin' })
            .then(function (r) { return r.json(); })
            .then(function (j) {
                var b = document.getElementById('commHistBody'); if (!b) { return; }
                var rows = (j && j.rows) || [];
                if (j && j.error) { b.innerHTML = '<span style="color:var(--red)">' + j.error + '</span>'; return; }
                if (!rows.length) { b.innerHTML = 'No history recorded for this entry yet (entries made before this feature have no trail).'; return; }
                var colFor = { created: '#0891b2', edited: '#d97706', approved: '#15803d', rejected: '#b91c1c', reopened: '#d97706', locked: '#334155', payslip: '#334155' };
                b.innerHTML = rows.map(function (l) {
                    var col = colFor[l.action] || 'var(--text2)';
                    return '<div style="display:flex;gap:12px;padding:9px 0;border-bottom:1px solid var(--border);align-items:flex-start">'
                        + '<span style="flex:none;min-width:120px;color:var(--text3);font-size:12px">' + (l.at || '') + '</span>'
                        + '<span style="flex:none;min-width:84px;font-weight:800;text-transform:uppercase;font-size:11px;color:' + col + '">' + l.action + '</span>'
                        + '<span style="color:var(--text2);line-height:1.5;font-size:12.5px">' + (l.details || '') + (l.by ? ' <span style="color:var(--text3)">&mdash; ' + l.by + '</span>' : '') + '</span></div>';
                }).join('');
            }).catch(function () { var b = document.getElementById('commHistBody'); if (b) { b.innerHTML = '<span style="color:var(--red)">Could not load history.</span>'; } });
    };
    window.commEdit = function (id) {
        var d = window.__REQ['commissions']; var r = d && (d.rows || []).find(function (x) { return x.id === id; });
        if (!r) { return; }
        var inp2 = 'width:100%;padding:9px 11px;border:1.5px solid var(--border);border-radius:9px;font-size:14px;background:#f8fafc;font-family:var(--font2)';
        var lbl2 = 'font-size:11px;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.4px;display:block;margin-bottom:4px';
        var esc = function (v) { return String(v == null ? '' : v).replace(/"/g, '&quot;'); };
        var fld = function (id2, label, type, val, oninput) {
            return '<div><label style="' + lbl2 + '">' + label + '</label><input id="' + id2 + '" type="' + type + '" value="' + esc(val) + '" style="' + inp2 + '"' + (oninput ? ' oninput="' + oninput + '"' : '') + '></div>';
        };
        var html = '<div class="card" style="max-width:640px;width:100%;padding:0">'
            + '<div style="display:flex;align-items:center;justify-content:space-between;padding:18px 22px;border-bottom:1px solid var(--border)"><h3 style="margin:0;font-size:17px">Edit Commission Entry #' + id + ' <span style="font-weight:500;font-size:12px;color:var(--text3)">' + r.employee + '</span></h3><button class="btn btn-outline btn-sm" onclick="commModalClose()"><i class="fas fa-xmark"></i></button></div>'
            + '<div style="padding:22px;display:grid;grid-template-columns:1fr 1fr;gap:14px">'
            + fld('ce_purpose', 'Purpose', 'text', r.purpose)
            + fld('ce_portfolio', 'Portfolio / Bank', 'text', r.portfolio)
            + fld('ce_cycle', 'Earned Month (e.g. May 2026)', 'text', r.cycleMonth)
            + fld('ce_payout', 'Payout Date', 'date', r.payoutDate)
            + fld('ce_gross', 'Gross Amount (₹)', 'number', r.grossAmount, 'ceCalc()')
            + fld('ce_tds', 'TDS %', 'number', r.tdsRate, 'ceCalc()')
            + '<div style="grid-column:1/-1"><label style="' + lbl2 + '">Short Description</label><input id="ce_desc" type="text" value="' + esc(r.descriptionText) + '" style="' + inp2 + '"></div>'
            + '<div style="grid-column:1/-1;font-size:12px;color:var(--text3)">Net auto-recalculates from Gross &minus; TDS. <b>Every change is written to this entry&#39;s history</b>' + (r.status === 'Approved' ? ' and will be marked &quot;edited AFTER approval&quot;.' : '.') + '</div>'
            + '</div>'
            + '<div style="display:flex;gap:10px;justify-content:flex-end;padding:0 22px 20px"><button class="btn btn-outline" onclick="commModalClose()">Cancel</button><button class="btn btn-primary" onclick="commEditSave(' + id + ')"><i class="fas fa-check"></i> Save changes</button></div></div>';
        commModal(html);
    };
    window.ceCalc = function () { /* informational only; server recomputes */ };
    window.commEditSave = function (id) {
        var g = function (x) { var el = document.getElementById(x); return el ? el.value : ''; };
        var payload = { purpose: g('ce_purpose'), portfolio: g('ce_portfolio'), cycle_month: g('ce_cycle'), payout_date: g('ce_payout'), description: g('ce_desc') };
        if (g('ce_gross') !== '') { payload.gross_amount = Number(g('ce_gross')); }
        if (g('ce_tds') !== '') { payload.tds_rate = Number(g('ce_tds')); }
        fetch(cfg.requestsBase + '/commissions/' + id + '/update', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': cfg.csrf, 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify(payload) })
            .then(function (r) { return r.json(); }).then(function (j) {
                if (!j || !j.ok) { if (typeof toast === 'function') { toast((j && j.error) || 'Could not save'); } return; }
                if (typeof toast === 'function') { toast(j.message || 'Saved'); }
                commModalClose(); requestLoad('commissions'); window.__LS = null;
            }).catch(function () { if (typeof toast === 'function') { toast('Could not save'); } });
    };
    window.commReopen = function (id) {
