        if (g.error) { return pghead('Geo-Fence Map', 'Error', manageBtn) + '<div class="card"><div style="padding:30px;color:var(--red)"><b>Could not load geofence rules.</b></div></div>'; }
        var list = rows.length ? rows.map(function (r, i) {
