    var RPRIO = { low: ['Low', '#64748b'], normal: ['Normal', '#3b82f6'], high: ['High', '#f59e0b'], urgent: ['Urgent', '#dc2626'] };
    function rqA(s) { return String(s == null ? '' : s).replace(/"/g, '&quot;'); }
