        var chipColors = { what: ['#993c1d', '#faece7', 'fa-circle-question', 'What is this screen for?'], can: ['#085041', '#e1f5ee', 'fa-wand-magic-sparkles', 'What you can do here'], how: ['#26215c', '#eeedfe', 'fa-list-ol', 'How to use it — step by step'] };
