        'policies': { type: 'policies', title: 'Policy Repository', sub: 'Board-approved recovery / collection policies, code of conduct and SOPs — versioned, with owner, effective date, board-approval date and review-due. Set "Acknowledgement required" for policies agents must accept.', fields: [
            { k: 'title', l: 'Policy Title' }, { k: 'category', l: 'Category', type: 'select', opts: ['recovery_policy', 'code_of_conduct', 'sop', 'data_privacy', 'grievance', 'hr', 'other'], optLabels: ['Recovery / Collection Policy', 'Code of Conduct', 'SOP', 'Data Privacy (DPDP)', 'Grievance Redressal', 'HR Policy', 'Other'] }, { k: 'version', l: 'Version (e.g. v1.0)' }, { k: 'owner', l: 'Policy Owner' }, { k: 'effective_date', l: 'Effective Date', type: 'date' }, { k: 'board_approved_on', l: 'Board Approved On', type: 'date' }, { k: 'review_due', l: 'Next Review Due', type: 'date' }, { k: 'ack_required', l: 'Acknowledgement Required', type: 'select', opts: ['1', '0'], optLabels: ['Yes — agents must acknowledge', 'No'] }, { k: 'reference', l: 'Document Link / Reference' }, { k: 'summary', l: 'Summary', type: 'textarea' }, { k: 'status', l: 'Status', type: 'select', opts: ['active', 'superseded', 'draft'], optLabels: ['Active (current)', 'Superseded', 'Draft'] }] },
        'messages': { type: 'messages', title: 'Messages', sub: 'Message / broadcast log', fields: [
