            { k: 'half_day_hours', l: 'Half Day (hours)', type: 'number', hint: 'Optional override, e.g. 4.5. Blank = use Late Policy' },
            { k: 'break_budget', l: 'Break Budget (minutes)', type: 'number', hint: 'Optional override. Blank = use Late Policy' }] },
